Object.assign(sourceCache, {"InputSystem/GestureAnalyzer.cs":"using System;\r\nusing System.Collections.Generic;\r\nusing Shield_Shot.InputSystem.Data;\r\nusing UnityEngine;\r\nusing Unity.Profiling;\r\nusing TouchPhase = UnityEngine.InputSystem.TouchPhase;\r\n\r\nnamespace Shield_Shot.InputSystem\r\n{\r\n    public class GestureAnalyzer : MonoBehaviour\r\n    {\r\n        [Header(\"Zone Identity\")]\r\n        [Tooltip(\"이 Analyzer가 어느 입력 존(공격/방어)에 속하는지. Inspector에서 반드시 맞게 지정할 것.\")]\r\n        [SerializeField] private InputZone _zone;\r\n\r\n        public InputZone Zone =\u003e _zone;\r\n\r\n        [Header(\"Threshold Settings\")]\r\n        [SerializeField] private float chargeWaitTime = 0.5f;\r\n        [SerializeField] private float minDragDistanceForCharge = 50f;\r\n\n        [Header(\"Diagnostics\")]\n        [SerializeField] private bool enableDebugLogging;\n\r\n        // 🌟 외부(무기/방패 매니저 등)에서 구독할 이벤트들\r\n        public event Action\u003cInputContext\u003e OnInputBegan;\r\n        public event Action\u003cInputContext\u003e OnInputStay;\r\n        public event Action\u003cInputContext\u003e OnInputUp;\r\n        public event Action\u003cInputContext\u003e OnInputCanceled;\r\n\r\n        // 기존 내부 데이터 추적용 딕셔너리\r\n        private Dictionary\u003cint, TrackedTouch\u003e trackedTouches = new();\r\n        private TrackedTouch activeChargingTouch;\r\n\r\n        private static readonly ProfilerMarker\r\n    GestureUpdateMarker =\r\n        new ProfilerMarker(\r\n            \"Input.V1.GestureUpdate\");\r\n\r\n        private void Update()\r\n        {\r\n            if (trackedTouches.Count == 0)\r\n            {\r\n                return;\r\n            }\r\n\r\n            GestureUpdateMarker.Begin();\r\n\r\n            try\r\n            {\r\n                foreach (TrackedTouch touch\r\n                         in trackedTouches.Values)\r\n                {\r\n                    if (touch.state ==\r\n                            GestureState.Charging ||\r\n                        touch.state ==\r\n                            GestureState.ChargedComplete)\r\n                    {\r\n                        continue;\r\n                    }\r\n\r\n                    float elapsed =\r\n                        Time.time -\r\n                        touch.startTime;\r\n\r\n                    if (minDragDistanceForCharge \u003e 0f)\r\n                    {\r\n                        float dragDist =\r\n                            Vector2.Distance(\r\n                                touch.startPosition,\r\n                                touch.currentPosition);\r\n\r\n                        if (dragDist \u003c\r\n                            minDragDistanceForCharge)\r\n                        {\r\n                            touch.lastMovedTime =\r\n                                Time.time;\r\n\r\n                            continue;\r\n                        }\r\n\r\n                        elapsed =\r\n                            Time.time -\r\n                            touch.lastMovedTime;\r\n                    }\r\n\r\n                    FireContextEvent(\r\n                        touch,\r\n                        GestureState.Tracking,\r\n                        OnInputStay);\r\n\r\n                    if (elapsed \u003e= chargeWaitTime \u0026\u0026\r\n                        !touch.isChargingTriggered)\r\n                    {\r\n                        touch.state =\r\n                            GestureState.Charging;\r\n\r\n                        touch.isChargingTriggered =\r\n                            true;\r\n\r\n                        activeChargingTouch =\r\n                            touch;\r\n\r\n                        if (enableDebugLogging)\n                        {\n                            Debug.Log(\n                                $\"🔥 차징 시작! \" +\n                                $\"(Finger: {touch.fingerId})\");\n                        }\n                    }\r\n                }\r\n\r\n                if (activeChargingTouch != null \u0026\u0026\r\n                    trackedTouches.ContainsKey(\r\n                        activeChargingTouch.fingerId))\r\n                {\r\n                    FireContextEvent(\r\n                        activeChargingTouch,\r\n                        GestureState.Charging,\r\n                        OnInputStay);\r\n                }\r\n            }\r\n            finally\r\n            {\r\n                GestureUpdateMarker.End();\r\n            }\r\n        }\r\n\r\n        #region TouchRouter로부터 원시 터치 수신\r\n        public void ReceiveRawTouch(int fingerId, Vector2 touchPos, TouchPhase phase)\r\n        {\r\n            switch (phase)\r\n            {\r\n                case TouchPhase.Began: OnTouchBegan(fingerId, touchPos); break;\r\n                case TouchPhase.Moved: OnTouchMoved(fingerId, touchPos); break;\r\n                case TouchPhase.Stationary:\r\n                    if (trackedTouches.TryGetValue(fingerId, out var t))\r\n                        t.currentPosition = touchPos;\r\n                    break;\r\n                case TouchPhase.Ended:\r\n                case TouchPhase.Canceled: OnTouchEnded(fingerId, touchPos, phase); break;\r\n            }\r\n        }\r\n        #endregion\r\n\r\n        #region 내부 터치 단계 처리\r\n        private void OnTouchBegan(int fingerId, Vector2 pos)\r\n        {\r\n            if (trackedTouches.ContainsKey(fingerId)) return;\r\n\r\n            var newTouch = new TrackedTouch\r\n            {\r\n                fingerId = fingerId,\r\n                startPosition = pos,\r\n                currentPosition = pos,\r\n                startTime = Time.time,\r\n                lastMovedTime = Time.time,\r\n                state = GestureState.Tracking\r\n            };\r\n            trackedTouches.Add(fingerId, newTouch);\r\n\r\n            FireContextEvent(newTouch, GestureState.Tracking, OnInputBegan);\r\n        }\r\n\r\n        private void OnTouchMoved(int fingerId, Vector2 pos)\r\n        {\r\n            if (!trackedTouches.TryGetValue(fingerId, out var touch)) return;\r\n\r\n            float moveDist = Vector2.Distance(touch.currentPosition, pos);\r\n            touch.currentPosition = pos;\r\n\r\n            // 활(Bow) 등에서 드래그 도중 차징이 취소되는 예외 처리 조건\r\n            if (minDragDistanceForCharge \u003e 0f \u0026\u0026 moveDist \u003e 100.0f)\r\n            {\r\n                touch.lastMovedTime = Time.time;\r\n\r\n                if (touch.state == GestureState.Charging || touch.state == GestureState.ChargedComplete)\r\n                {\r\n                    touch.state = GestureState.Tracking;\r\n                    touch.isChargingTriggered = false;\r\n                    activeChargingTouch = null;\r\n\r\n                    FireContextEvent(touch, GestureState.Canceled, OnInputCanceled);\r\n                }\r\n            }\r\n        }\r\n\r\n        private void OnTouchEnded(int fingerId, Vector2 pos, TouchPhase phase)\r\n        {\r\n            if (!trackedTouches.TryGetValue(fingerId, out var touch)) return;\r\n            touch.currentPosition = pos;\r\n\r\n            if (phase != TouchPhase.Canceled)\r\n            {\r\n                // 손을 정상적으로 뗐을 때 기존 상태가 차징이었다면 그 상태 유지해서 Up 이벤트 송출\r\n                GestureState finalState = (touch.state == GestureState.Charging) ? GestureState.Charging : GestureState.Released;\r\n                FireContextEvent(touch, finalState, OnInputUp);\r\n            }\r\n            else\r\n            {\r\n                FireContextEvent(touch, GestureState.Canceled, OnInputCanceled);\r\n            }\r\n\r\n            if (activeChargingTouch?.fingerId == fingerId)\r\n                activeChargingTouch = null;\r\n\r\n            trackedTouches.Remove(fingerId);\r\n        }\r\n        #endregion\r\n\r\n        // InputContext와 GestureState로 데이터를 포장하여 이벤트를 실행하는 메서드\r\n        private void FireContextEvent(TrackedTouch touch, GestureState inputState, Action\u003cInputContext\u003e targetEvent)\r\n        {\r\n            if (targetEvent == null) return;\r\n\r\n            InputContext ctx = new InputContext\r\n            {\r\n                fingerId = touch.fingerId,\r\n                state = inputState,\r\n                holdTime = Time.time - touch.startTime,\r\n                dragVector = touch.currentPosition - touch.startPosition,\r\n                totalDistance = Vector2.Distance(touch.startPosition, touch.currentPosition),\r\n                startPosition = touch.startPosition\r\n            };\r\n\r\n            targetEvent.Invoke(ctx);\r\n        }\r\n\r\n        public void ResetTracking(\r\n    bool notifyCancellation = true)\r\n        {\r\n            if (notifyCancellation \u0026\u0026\r\n                OnInputCanceled != null)\r\n            {\r\n                foreach (TrackedTouch touch\r\n                         in trackedTouches.Values)\r\n                {\r\n                    FireContextEvent(\r\n                        touch,\r\n                        GestureState.Canceled,\r\n                        OnInputCanceled);\r\n                }\r\n            }\r\n\r\n            trackedTouches.Clear();\r\n            activeChargingTouch = null;\r\n        }\r\n    }\r\n}","InputSystem/InputProvider.cs":"using System.Collections.Generic; // 💡 HashSet 사용을 위해 추가\r\nusing UnityEngine;\r\nusing UnityEngine.InputSystem;\r\nusing UnityEngine.InputSystem.EnhancedTouch;\r\nusing UnityEngine.EventSystems;\r\n\r\nusing TouchPhase = UnityEngine.InputSystem.TouchPhase;\r\n\r\nnamespace Shield_Shot.InputSystem\r\n{\r\n    public class InputProvider : MonoBehaviour\r\n    {\r\n        [Header(\"Router 참조\")]\r\n        [SerializeField] private TouchRouter touchRouter;\r\n\r\n        // 💡 [핵심] UI에서 시작된 손가락 ID(또는 마우스 -1)를 기억하는 블랙리스트 저장소\r\n        private HashSet\u003cint\u003e uiIgnoredFingers = new HashSet\u003cint\u003e();\r\n\r\n        private void OnEnable()\r\n        {\r\n            EnhancedTouchSupport.Enable();\r\n        }\r\n\r\n        private void OnDisable()\r\n        {\r\n            touchRouter?.ResetRouting(\r\n                notifyCancellation: true);\r\n\r\n            uiIgnoredFingers.Clear();\r\n            EnhancedTouchSupport.Disable();\r\n        }\r\n\r\n        private void Update()\r\n        {\r\n            if (touchRouter == null) return;\r\n\r\n            // 1. 실제 모바일/태블릿 터치 처리 (EnhancedTouch)\r\n            var activeTouches = UnityEngine.InputSystem.EnhancedTouch.Touch.activeTouches;\r\n            if (activeTouches.Count \u003e 0)\r\n            {\r\n                foreach (var touch in activeTouches)\r\n                {\r\n                    int id = touch.finger.index;\r\n\r\n                    // [처리 1] 새로운 터치가 시작될 때 UI 위였다면 블랙리스트에 등록\r\n                    if (touch.phase == TouchPhase.Began)\r\n                    {\r\n                        if (IsUIBlocked(id))\r\n                        {\r\n                            uiIgnoredFingers.Add(id);\r\n                            continue; // 인게임 라우터로 안 보냄\r\n                        }\r\n                    }\r\n\r\n                    // [처리 2] 이미 UI에서 시작된 손가락이라면 움직이거나 멈춰도 무조건 패스\r\n                    if (uiIgnoredFingers.Contains(id))\r\n                    {\r\n                        // 터치가 끝나면 블랙리스트에서 해제해줍니다.\r\n                        if (touch.phase == TouchPhase.Ended || touch.phase == TouchPhase.Canceled)\r\n                        {\r\n                            uiIgnoredFingers.Remove(id);\r\n                        }\r\n                        continue;\r\n                    }\r\n\r\n                    // [처리 3] UI가 아닌 순수 인게임 터치만 라우터로 배송\r\n                    touchRouter.ProcessTouch(id, touch.screenPosition, touch.phase);\r\n                }\r\n            }\r\n            // 2. 터치가 없을 경우 PC 에디터용 마우스 시뮬레이션\r\n            else if (Pointer.current != null)\r\n            {\r\n                SimulateMouseAsTouch();\r\n            }\r\n        }\r\n\r\n        private void SimulateMouseAsTouch()\r\n        {\r\n            var pointer = Pointer.current;\r\n            Vector2 mousePos = pointer.position.ReadValue();\r\n            bool isPressed = pointer.press.isPressed;\r\n            bool wasPressedThisFrame = pointer.press.wasPressedThisFrame;\r\n            bool wasReleasedThisFrame = pointer.press.wasReleasedThisFrame;\r\n\r\n            int mouseId = -1; // 마우스는 편의상 -1 고정\r\n\r\n            // 마우스 클릭 시작 시 UI 위라면 블랙리스트 등록\r\n            if (wasPressedThisFrame)\r\n            {\r\n                if (IsUIBlocked(mouseId))\r\n                {\r\n                    uiIgnoredFingers.Add(mouseId);\r\n                    return;\r\n                }\r\n            }\r\n\r\n            // 블랙리스트에 있으면 마우스 드래그/업 이벤트 전부 인게임 스킵\r\n            if (uiIgnoredFingers.Contains(mouseId))\r\n            {\r\n                if (wasReleasedThisFrame)\r\n                {\r\n                    uiIgnoredFingers.Remove(mouseId);\r\n                }\r\n                return;\r\n            }\r\n\r\n            // 순수 인게임 마우스 클릭 처리\r\n            if (wasPressedThisFrame)\r\n            {\r\n                touchRouter.ProcessTouch(mouseId, mousePos, TouchPhase.Began);\r\n            }\r\n            else if (isPressed)\r\n            {\r\n                Vector2 delta = pointer.delta.ReadValue();\r\n                TouchPhase phase = (delta.sqrMagnitude \u003e 0.01f) ? TouchPhase.Moved : TouchPhase.Stationary;\r\n                touchRouter.ProcessTouch(mouseId, mousePos, phase);\r\n            }\r\n            else if (wasReleasedThisFrame)\r\n            {\r\n                touchRouter.ProcessTouch(mouseId, mousePos, TouchPhase.Ended);\r\n            }\r\n        }\r\n\r\n        private bool IsUIBlocked(int pointerId)\r\n        {\r\n            if (EventSystem.current == null) return false;\r\n            return EventSystem.current.IsPointerOverGameObject(pointerId);\r\n        }\r\n    }\r\n}","InputSystemV2/Application/AttackGestureInterpreter.cs":"using System;\r\nusing System.Collections.Generic;\r\nusing Shield_Shot.InputSystemV2.Application;\r\nusing Shield_Shot.InputSystemV2.Combat.Domain;\r\nusing Shield_Shot.InputSystemV2.Domain;\r\nusing Shield_Shot.InputSystemV2.Gestures.Application;\r\nusing Shield_Shot.InputSystemV2.Gestures.Domain;\r\nusing UnityEngine;\r\n\r\nnamespace Shield_Shot.InputSystemV2.Combat.Application\r\n{\r\n    public sealed class AttackGestureInterpreter\r\n        : IPointerGestureSink\r\n    {\r\n        private readonly IAttackChargeSettingsProvider\r\n            settingsProvider;\r\n\r\n        private readonly IPointerViewportProvider\r\n            viewportProvider;\r\n\r\n        private readonly IInputClock clock;\r\n        private readonly IAttackInputSink next;\r\n\r\n        private readonly Dictionary\u003cPointerKey, ActiveAttack\u003e\r\n            activeAttacks;\r\n\r\n        public AttackGestureInterpreter(\r\n            IAttackChargeSettingsProvider settingsProvider,\r\n            IPointerViewportProvider viewportProvider,\r\n            IInputClock clock,\r\n            IAttackInputSink next,\r\n            int initialPointerCapacity = 2)\r\n        {\r\n            this.settingsProvider = settingsProvider\r\n                ?? throw new ArgumentNullException(\r\n                    nameof(settingsProvider));\r\n\r\n            this.viewportProvider = viewportProvider\r\n                ?? throw new ArgumentNullException(\r\n                    nameof(viewportProvider));\r\n\r\n            this.clock = clock\r\n                ?? throw new ArgumentNullException(\r\n                    nameof(clock));\r\n\r\n            this.next = next\r\n                ?? throw new ArgumentNullException(\r\n                    nameof(next));\r\n\r\n            if (initialPointerCapacity \u003c= 0)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(initialPointerCapacity));\r\n            }\r\n\r\n            activeAttacks =\r\n                new Dictionary\u003cPointerKey, ActiveAttack\u003e(\r\n                    initialPointerCapacity);\r\n        }\r\n\r\n        public void Receive(\r\n            in PointerGestureSample gesture)\r\n        {\r\n            switch (gesture.Phase)\r\n            {\r\n                case PointerGesturePhase.Began:\r\n                    Begin(in gesture);\r\n                    break;\r\n\r\n                case PointerGesturePhase.Changed:\r\n                    Change(in gesture);\r\n                    break;\r\n\r\n                case PointerGesturePhase.Completed:\r\n                    End(\r\n                        in gesture,\r\n                        AttackInputPhase.Released);\r\n                    break;\r\n\r\n                case PointerGesturePhase.Canceled:\r\n                    End(\r\n                        in gesture,\r\n                        AttackInputPhase.Canceled);\r\n                    break;\r\n            }\r\n        }\r\n\r\n        public void Tick()\r\n        {\r\n            double timestamp = clock.Now;\r\n\r\n            foreach (KeyValuePair\u003cPointerKey, ActiveAttack\u003e entry\r\n                     in activeAttacks)\r\n            {\r\n                ActiveAttack attack =\r\n                    entry.Value;\r\n\r\n                if (!attack.IsAimEligible)\r\n                {\r\n                    continue;\r\n                }\r\n\r\n                bool stateChanged =\r\n                    EvaluateCharge(\r\n                        attack,\r\n                        timestamp);\r\n\r\n                if (attack.ChargeState ==\r\n                    AttackChargeState.Aiming)\r\n                {\r\n                    continue;\r\n                }\r\n\r\n                bool signalIntervalReached =\r\n                    timestamp -\r\n                    attack.LastChargeSignalTimestamp \u003e=\r\n                    attack.Settings.ChargeSignalInterval;\r\n\r\n                if (!stateChanged \u0026\u0026\r\n                    !signalIntervalReached)\r\n                {\r\n                    continue;\r\n                }\r\n\r\n                if (!stateChanged \u0026\u0026\r\n                    attack.ChargeState ==\r\n                    AttackChargeState.FullyCharged)\r\n                {\r\n                    continue;\r\n                }\r\n\r\n                attack.LastChargeSignalTimestamp =\r\n                    timestamp;\r\n\r\n                Emit(\r\n                    attack.Pointer,\r\n                    AttackInputPhase.ChargeChanged,\r\n                    attack,\r\n                    timestamp);\r\n            }\r\n        }\r\n\r\n        public void Reset()\r\n        {\r\n            activeAttacks.Clear();\r\n        }\r\n\r\n        private void Begin(\r\n            in PointerGestureSample gesture)\r\n        {\r\n            if (activeAttacks.TryGetValue(\r\n                    gesture.Pointer,\r\n                    out ActiveAttack previousAttack))\r\n            {\r\n                EvaluateCharge(\r\n                    previousAttack,\r\n                    gesture.Timestamp);\r\n\r\n                Emit(\r\n                    previousAttack.Pointer,\r\n                    AttackInputPhase.Canceled,\r\n                    previousAttack,\r\n                    gesture.Timestamp);\r\n\r\n                activeAttacks.Remove(\r\n                    gesture.Pointer);\r\n            }\r\n\r\n            Rect viewport =\r\n                viewportProvider.CurrentViewport;\r\n\r\n            if (viewport.width \u003c= 0f ||\r\n                viewport.height \u003c= 0f)\r\n            {\r\n                return;\r\n            }\r\n\r\n            AttackChargeSettings settings =\r\n                settingsProvider.CurrentSettings;\r\n\r\n            float shortSide =\r\n                Mathf.Min(\r\n                    viewport.width,\r\n                    viewport.height);\r\n\r\n            float minimumAimDistance =\r\n                shortSide *\r\n                settings.MinimumAimDistanceRatio;\r\n\r\n            ActiveAttack attack =\r\n                new ActiveAttack(\r\n                    gesture.Pointer,\r\n                    settings,\r\n                    minimumAimDistance *\r\n                    minimumAimDistance,\r\n                    gesture.Timestamp);\r\n\r\n            activeAttacks.Add(\r\n                gesture.Pointer,\r\n                attack);\r\n\r\n            Emit(\r\n                gesture.Pointer,\r\n                AttackInputPhase.Began,\r\n                attack,\r\n                gesture.Timestamp);\r\n        }\r\n\r\n        private void Change(\r\n            in PointerGestureSample gesture)\r\n        {\r\n            if (!activeAttacks.TryGetValue(\r\n                    gesture.Pointer,\r\n                    out ActiveAttack attack))\r\n            {\r\n                return;\r\n            }\r\n\r\n            attack.AimVector =\r\n                gesture.Displacement;\r\n\r\n            bool isAimEligible =\r\n                gesture.DisplacementSquared \u003e=\r\n                attack.MinimumAimDistanceSquared;\r\n\r\n            if (isAimEligible \u0026\u0026\r\n                !attack.IsAimEligible)\r\n            {\r\n                attack.IsAimEligible = true;\r\n                attack.AimEligibleTimestamp =\r\n                    gesture.Timestamp;\r\n            }\r\n            else if (!isAimEligible \u0026\u0026\r\n                     attack.IsAimEligible)\r\n            {\r\n                attack.IsAimEligible = false;\r\n                attack.ChargeState =\r\n                    AttackChargeState.Aiming;\r\n\r\n                attack.ChargeRatio = 0f;\r\n                attack.AimEligibleTimestamp = 0d;\r\n            }\r\n\r\n            bool stateChanged =\r\n                EvaluateCharge(\r\n                    attack,\r\n                    gesture.Timestamp);\r\n\r\n            if (stateChanged)\r\n            {\r\n                attack.LastChargeSignalTimestamp =\r\n                    gesture.Timestamp;\r\n            }\r\n\r\n            Emit(\r\n                gesture.Pointer,\r\n                AttackInputPhase.AimChanged,\r\n                attack,\r\n                gesture.Timestamp);\r\n        }\r\n\r\n        private void End(\r\n            in PointerGestureSample gesture,\r\n            AttackInputPhase finalPhase)\r\n        {\r\n            if (!activeAttacks.TryGetValue(\r\n                    gesture.Pointer,\r\n                    out ActiveAttack attack))\r\n            {\r\n                return;\r\n            }\r\n\r\n            attack.AimVector =\r\n                gesture.Displacement;\r\n\r\n            EvaluateCharge(\r\n                attack,\r\n                gesture.Timestamp);\r\n\r\n            activeAttacks.Remove(\r\n                gesture.Pointer);\r\n\r\n            Emit(\r\n                gesture.Pointer,\r\n                finalPhase,\r\n                attack,\r\n                gesture.Timestamp);\r\n        }\r\n\r\n        private static bool EvaluateCharge(\r\n            ActiveAttack attack,\r\n            double timestamp)\r\n        {\r\n            AttackChargeState previousState =\r\n                attack.ChargeState;\r\n\r\n            if (!attack.IsAimEligible)\r\n            {\r\n                attack.ChargeState =\r\n                    AttackChargeState.Aiming;\r\n\r\n                attack.ChargeRatio = 0f;\r\n\r\n                return previousState !=\r\n                       attack.ChargeState;\r\n            }\r\n\r\n            double chargeStartTimestamp =\r\n                attack.AimEligibleTimestamp +\r\n                attack.Settings.ChargeStartDelay;\r\n\r\n            if (timestamp \u003c\r\n                chargeStartTimestamp)\r\n            {\r\n                attack.ChargeState =\r\n                    AttackChargeState.Aiming;\r\n\r\n                attack.ChargeRatio = 0f;\r\n\r\n                return previousState !=\r\n                       attack.ChargeState;\r\n            }\r\n\r\n            double chargeElapsed =\r\n                timestamp -\r\n                chargeStartTimestamp;\r\n\r\n            attack.ChargeRatio =\r\n                Mathf.Clamp01(\r\n                    (float)(\r\n                        chargeElapsed /\r\n                        attack.Settings.FullChargeDuration));\r\n\r\n            attack.ChargeState =\r\n                attack.ChargeRatio \u003e= 1f\r\n                    ? AttackChargeState.FullyCharged\r\n                    : AttackChargeState.Charging;\r\n\r\n            return previousState !=\r\n                   attack.ChargeState;\r\n        }\r\n\r\n        private void Emit(\r\n            PointerKey pointer,\r\n            AttackInputPhase phase,\r\n            ActiveAttack attack,\r\n            double timestamp)\r\n        {\r\n            AttackInputSample sample =\r\n                new AttackInputSample(\r\n                    pointer,\r\n                    phase,\r\n                    attack.ChargeState,\r\n                    attack.AimVector,\r\n                    attack.IsAimEligible,\r\n                    attack.ChargeRatio,\r\n                    timestamp);\r\n\r\n            next.Receive(in sample);\r\n        }\r\n\r\n        private sealed class ActiveAttack\r\n        {\r\n            public PointerKey Pointer { get; }\r\n            public AttackChargeSettings Settings { get; }\r\n            public float MinimumAimDistanceSquared { get; }\r\n\r\n            public Vector2 AimVector;\r\n            public bool IsAimEligible;\r\n            public double AimEligibleTimestamp;\r\n            public double LastChargeSignalTimestamp;\r\n\r\n            public AttackChargeState ChargeState;\r\n            public float ChargeRatio;\r\n\r\n            public ActiveAttack(\r\n                PointerKey pointer,\r\n                AttackChargeSettings settings,\r\n                float minimumAimDistanceSquared,\r\n                double startTimestamp)\r\n            {\r\n                Pointer = pointer;\r\n                Settings = settings;\r\n\r\n                MinimumAimDistanceSquared =\r\n                    minimumAimDistanceSquared;\r\n\r\n                AimVector = Vector2.zero;\r\n                IsAimEligible = false;\r\n                AimEligibleTimestamp = 0d;\r\n\r\n                LastChargeSignalTimestamp =\r\n                    startTimestamp;\r\n\r\n                ChargeState =\r\n                    AttackChargeState.Aiming;\r\n\r\n                ChargeRatio = 0f;\r\n            }\r\n        }\r\n    }\r\n}","InputSystemV2/Application/CombatPointerRouter.cs":"using System;\r\nusing System.Collections.Generic;\r\nusing Shield_Shot.InputSystemV2.Application;\r\nusing Shield_Shot.InputSystemV2.Combat.Domain;\r\nusing Shield_Shot.InputSystemV2.Domain;\r\n\r\nnamespace Shield_Shot.InputSystemV2.Combat.Application\r\n{\r\n    public sealed class CombatPointerRouter\r\n        : IPointerSampleSink\r\n    {\r\n        private readonly ICombatInputChannelResolver\r\n            channelResolver;\r\n\r\n        private readonly IPointerSampleSink attackSink;\r\n        private readonly IPointerSampleSink defenseSink;\r\n\r\n        private readonly Dictionary\u003cPointerKey, CombatInputChannel\u003e\r\n            activeChannels;\r\n\r\n        public CombatPointerRouter(\r\n            ICombatInputChannelResolver channelResolver,\r\n            IPointerSampleSink attackSink,\r\n            IPointerSampleSink defenseSink,\r\n            int initialPointerCapacity = 4)\r\n        {\r\n            this.channelResolver = channelResolver\r\n                ?? throw new ArgumentNullException(\r\n                    nameof(channelResolver));\r\n\r\n            this.attackSink = attackSink\r\n                ?? throw new ArgumentNullException(\r\n                    nameof(attackSink));\r\n\r\n            this.defenseSink = defenseSink\r\n                ?? throw new ArgumentNullException(\r\n                    nameof(defenseSink));\r\n\r\n            if (initialPointerCapacity \u003c= 0)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(initialPointerCapacity));\r\n            }\r\n\r\n            activeChannels =\r\n                new Dictionary\u003cPointerKey, CombatInputChannel\u003e(\r\n                    initialPointerCapacity);\r\n        }\r\n\r\n        public void Receive(in PointerSample sample)\r\n        {\r\n            PointerKey key =\r\n                PointerKey.From(in sample);\r\n\r\n            if (sample.Phase == PointerPhase.Began)\r\n            {\r\n                CombatInputChannel channel =\r\n                    channelResolver.Resolve(in sample);\r\n\r\n                if (channel == CombatInputChannel.Unknown)\r\n                {\r\n                    return;\r\n                }\r\n\r\n                activeChannels[key] = channel;\r\n                Route(channel, in sample);\r\n                return;\r\n            }\r\n\r\n            if (!activeChannels.TryGetValue(\r\n                    key,\r\n                    out CombatInputChannel activeChannel))\r\n            {\r\n                return;\r\n            }\r\n\r\n            Route(activeChannel, in sample);\r\n\r\n            if (sample.Phase == PointerPhase.Ended ||\r\n                sample.Phase == PointerPhase.Canceled)\r\n            {\r\n                activeChannels.Remove(key);\r\n            }\r\n        }\r\n\r\n        public void Reset()\r\n        {\r\n            activeChannels.Clear();\r\n        }\r\n\r\n        private void Route(\r\n            CombatInputChannel channel,\r\n            in PointerSample sample)\r\n        {\r\n            switch (channel)\r\n            {\r\n                case CombatInputChannel.Attack:\r\n                    attackSink.Receive(in sample);\r\n                    break;\r\n\r\n                case CombatInputChannel.Defense:\r\n                    defenseSink.Receive(in sample);\r\n                    break;\r\n            }\r\n        }\r\n    }\r\n}","InputSystemV2/Application/DefenseGestureInterpreter.cs":"using System;\r\nusing Shield_Shot.InputSystemV2.Combat.Domain;\r\nusing Shield_Shot.InputSystemV2.Gestures.Application;\r\nusing Shield_Shot.InputSystemV2.Gestures.Domain;\r\n\r\nnamespace Shield_Shot.InputSystemV2.Combat.Application\r\n{\r\n    public sealed class DefenseGestureInterpreter\r\n        : IPointerGestureSink\r\n    {\r\n        private readonly IDefenseInputSink next;\r\n\r\n        public DefenseGestureInterpreter(\r\n            IDefenseInputSink next)\r\n        {\r\n            this.next = next\r\n                ?? throw new ArgumentNullException(\r\n                    nameof(next));\r\n        }\r\n\r\n        public void Receive(\r\n            in PointerGestureSample gesture)\r\n        {\r\n            DefenseInputPhase phase =\r\n                ConvertPhase(gesture.Phase);\r\n\r\n            var sample =\r\n                new DefenseInputSample(\r\n                    pointer: gesture.Pointer,\r\n                    phase: phase,\r\n                    startPosition: gesture.StartPosition,\r\n                    currentPosition: gesture.CurrentPosition,\r\n                    displacement: gesture.Displacement,\r\n                    timestamp: gesture.Timestamp);\r\n\r\n            next.Receive(in sample);\r\n        }\r\n\r\n        private static DefenseInputPhase ConvertPhase(\r\n            PointerGesturePhase phase)\r\n        {\r\n            switch (phase)\r\n            {\r\n                case PointerGesturePhase.Began:\r\n                    return DefenseInputPhase.Began;\r\n\r\n                case PointerGesturePhase.Changed:\r\n                    return DefenseInputPhase.DirectionChanged;\r\n\r\n                case PointerGesturePhase.Completed:\r\n                    return DefenseInputPhase.Released;\r\n\r\n                case PointerGesturePhase.Canceled:\r\n                    return DefenseInputPhase.Canceled;\r\n\r\n                default:\r\n                    throw new ArgumentOutOfRangeException(\r\n                        nameof(phase),\r\n                        phase,\r\n                        \"Unsupported pointer gesture phase.\");\r\n            }\r\n        }\r\n    }\r\n}","InputSystemV2/Application/PointerGestureTracker.cs":"using System;\r\nusing System.Collections.Generic;\r\nusing Shield_Shot.InputSystemV2.Application;\r\nusing Shield_Shot.InputSystemV2.Domain;\r\nusing Shield_Shot.InputSystemV2.Gestures.Domain;\r\nusing UnityEngine;\r\n\r\nnamespace Shield_Shot.InputSystemV2.Gestures.Application\r\n{\r\n    public sealed class PointerGestureTracker\r\n        : IPointerSampleSink\r\n    {\r\n        private readonly IPointerGestureSink next;\r\n\r\n        private readonly Dictionary\u003cPointerKey, TrackedGesture\u003e\r\n            trackedGestures;\r\n\r\n        public PointerGestureTracker(\r\n            IPointerGestureSink next,\r\n            int initialPointerCapacity = 4)\r\n        {\r\n            this.next = next\r\n                ?? throw new ArgumentNullException(\r\n                    nameof(next));\r\n\r\n            if (initialPointerCapacity \u003c= 0)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(initialPointerCapacity));\r\n            }\r\n\r\n            trackedGestures =\r\n                new Dictionary\u003cPointerKey, TrackedGesture\u003e(\r\n                    initialPointerCapacity);\r\n        }\r\n\r\n        public void Receive(in PointerSample sample)\r\n        {\r\n            PointerKey key =\r\n                PointerKey.From(in sample);\r\n\r\n            switch (sample.Phase)\r\n            {\r\n                case PointerPhase.Began:\r\n                    Begin(key, in sample);\r\n                    break;\r\n\r\n                case PointerPhase.Moved:\r\n                    Change(key, in sample);\r\n                    break;\r\n\r\n                case PointerPhase.Stationary:\r\n                    break;\r\n\r\n                case PointerPhase.Ended:\r\n                    End(\r\n                        key,\r\n                        PointerGesturePhase.Completed,\r\n                        in sample);\r\n                    break;\r\n\r\n                case PointerPhase.Canceled:\r\n                    End(\r\n                        key,\r\n                        PointerGesturePhase.Canceled,\r\n                        in sample);\r\n                    break;\r\n            }\r\n        }\r\n\r\n        public void Reset()\r\n        {\r\n            trackedGestures.Clear();\r\n        }\r\n\r\n        private void Begin(\r\n            PointerKey key,\r\n            in PointerSample sample)\r\n        {\r\n            TrackedGesture tracked =\r\n                new TrackedGesture(\r\n                    sample.ScreenPosition,\r\n                    sample.Timestamp);\r\n\r\n            trackedGestures[key] = tracked;\r\n\r\n            PointerGestureSample gesture =\r\n                new PointerGestureSample(\r\n                    pointer: key,\r\n                    phase: PointerGesturePhase.Began,\r\n                    startPosition: tracked.StartPosition,\r\n                    previousPosition: tracked.CurrentPosition,\r\n                    currentPosition: tracked.CurrentPosition,\r\n                    startTimestamp: tracked.StartTimestamp,\r\n                    timestamp: sample.Timestamp);\r\n\r\n            next.Receive(in gesture);\r\n        }\r\n\r\n        private void Change(\r\n            PointerKey key,\r\n            in PointerSample sample)\r\n        {\r\n            if (!trackedGestures.TryGetValue(\r\n                    key,\r\n                    out TrackedGesture tracked))\r\n            {\r\n                return;\r\n            }\r\n\r\n            PointerGestureSample gesture =\r\n                new PointerGestureSample(\r\n                    pointer: key,\r\n                    phase: PointerGesturePhase.Changed,\r\n                    startPosition: tracked.StartPosition,\r\n                    previousPosition: tracked.CurrentPosition,\r\n                    currentPosition: sample.ScreenPosition,\r\n                    startTimestamp: tracked.StartTimestamp,\r\n                    timestamp: sample.Timestamp);\r\n\r\n            tracked.CurrentPosition =\r\n                sample.ScreenPosition;\r\n\r\n            trackedGestures[key] = tracked;\r\n\r\n            next.Receive(in gesture);\r\n        }\r\n\r\n        private void End(\r\n            PointerKey key,\r\n            PointerGesturePhase finalPhase,\r\n            in PointerSample sample)\r\n        {\r\n            if (!trackedGestures.TryGetValue(\r\n                    key,\r\n                    out TrackedGesture tracked))\r\n            {\r\n                return;\r\n            }\r\n\r\n            trackedGestures.Remove(key);\r\n\r\n            PointerGestureSample gesture =\r\n                new PointerGestureSample(\r\n                    pointer: key,\r\n                    phase: finalPhase,\r\n                    startPosition: tracked.StartPosition,\r\n                    previousPosition: tracked.CurrentPosition,\r\n                    currentPosition: sample.ScreenPosition,\r\n                    startTimestamp: tracked.StartTimestamp,\r\n                    timestamp: sample.Timestamp);\r\n\r\n            next.Receive(in gesture);\r\n        }\r\n\r\n        private struct TrackedGesture\r\n        {\r\n            public Vector2 StartPosition;\r\n            public Vector2 CurrentPosition;\r\n            public double StartTimestamp;\r\n\r\n            public TrackedGesture(\r\n                Vector2 startPosition,\r\n                double startTimestamp)\r\n            {\r\n                StartPosition = startPosition;\r\n                CurrentPosition = startPosition;\r\n                StartTimestamp = startTimestamp;\r\n            }\r\n        }\r\n    }\r\n}","InputSystemV2/Application/PointerMoveCoalescingSink.cs":"using System;\r\nusing System.Collections.Generic;\r\nusing Shield_Shot.InputSystemV2.Domain;\r\n\r\nnamespace Shield_Shot.InputSystemV2.Application\r\n{\r\n    public sealed class PointerMoveCoalescingSink\r\n        : IPointerFrameSink\r\n    {\r\n        private readonly IPointerSampleSink next;\r\n\r\n        private readonly Dictionary\u003cPointerKey, PointerSample\u003e\r\n            pendingMovements;\r\n\r\n        public PointerMoveCoalescingSink(\r\n            IPointerSampleSink next,\r\n            int initialPointerCapacity = 4)\r\n        {\r\n            this.next = next\r\n                ?? throw new ArgumentNullException(nameof(next));\r\n\r\n            if (initialPointerCapacity \u003c= 0)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(initialPointerCapacity));\r\n            }\r\n\r\n            pendingMovements =\r\n                new Dictionary\u003cPointerKey, PointerSample\u003e(\r\n                    initialPointerCapacity);\r\n        }\r\n\r\n        public void Receive(in PointerSample sample)\r\n        {\r\n            PointerKey key =\r\n                PointerKey.From(in sample);\r\n\r\n            if (sample.Phase == PointerPhase.Moved)\r\n            {\r\n                pendingMovements[key] = sample;\r\n                return;\r\n            }\r\n\r\n            FlushMovement(key);\r\n            next.Receive(in sample);\r\n        }\r\n\r\n        public void CompleteFrame()\r\n        {\r\n            foreach (KeyValuePair\u003cPointerKey, PointerSample\u003e entry\r\n                     in pendingMovements)\r\n            {\r\n                PointerSample sample = entry.Value;\r\n                next.Receive(in sample);\r\n            }\r\n\r\n            pendingMovements.Clear();\r\n        }\r\n\r\n        public void Reset()\r\n        {\r\n            pendingMovements.Clear();\r\n        }\r\n\r\n        private void FlushMovement(PointerKey key)\r\n        {\r\n            if (!pendingMovements.TryGetValue(\r\n                    key,\r\n                    out PointerSample pendingSample))\r\n            {\r\n                return;\r\n            }\r\n\r\n            pendingMovements.Remove(key);\r\n            next.Receive(in pendingSample);\r\n        }\r\n    }\r\n}","InputSystemV2/Application/PointerMovementThresholdFilter.cs":"using System;\r\nusing System.Collections.Generic;\r\nusing Shield_Shot.InputSystemV2.Domain;\r\nusing UnityEngine;\r\n\r\nnamespace Shield_Shot.InputSystemV2.Application\r\n{\r\n    public sealed class PointerMovementThresholdFilter : IPointerFilter\r\n    {\r\n        private readonly float minimumDistanceSquared;\r\n        private readonly Dictionary\u003cPointerKey, Vector2\u003e\r\n            lastAcceptedPositions;\r\n\r\n        public PointerMovementThresholdFilter(\r\n            float minimumDistance,\r\n            int initialPointerCapacity = 4)\r\n        {\r\n            if (minimumDistance \u003c 0f)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(minimumDistance));\r\n            }\r\n\r\n            if (initialPointerCapacity \u003c= 0)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(initialPointerCapacity));\r\n            }\r\n\r\n            minimumDistanceSquared =\r\n                minimumDistance * minimumDistance;\r\n\r\n            lastAcceptedPositions =\r\n                new Dictionary\u003cPointerKey, Vector2\u003e(\r\n                    initialPointerCapacity);\r\n        }\r\n\r\n        public bool Accept(in PointerSample sample)\r\n        {\r\n            PointerKey key =\r\n                PointerKey.From(in sample);\r\n\r\n            switch (sample.Phase)\r\n            {\r\n                case PointerPhase.Began:\r\n                    lastAcceptedPositions[key] =\r\n                        sample.ScreenPosition;\r\n\r\n                    return true;\r\n\r\n                case PointerPhase.Moved:\r\n                    return AcceptMovement(\r\n                        key,\r\n                        sample.ScreenPosition);\r\n\r\n                case PointerPhase.Stationary:\r\n                    return false;\r\n\r\n                case PointerPhase.Ended:\r\n                case PointerPhase.Canceled:\r\n                    lastAcceptedPositions.Remove(key);\r\n                    return true;\r\n\r\n                default:\r\n                    return false;\r\n            }\r\n        }\r\n\r\n        private bool AcceptMovement(\r\n            PointerKey key,\r\n            Vector2 currentPosition)\r\n        {\r\n            if (!lastAcceptedPositions.TryGetValue(\r\n                    key,\r\n                    out Vector2 previousPosition))\r\n            {\r\n                lastAcceptedPositions[key] =\r\n                    currentPosition;\r\n\r\n                return true;\r\n            }\r\n\r\n            Vector2 delta =\r\n                currentPosition - previousPosition;\r\n\r\n            if (delta.sqrMagnitude \u003c\r\n                minimumDistanceSquared)\r\n            {\r\n                return false;\r\n            }\r\n\r\n            lastAcceptedPositions[key] =\r\n                currentPosition;\r\n\r\n            return true;\r\n        }\r\n\r\n        public void Reset()\r\n        {\r\n            lastAcceptedPositions.Clear();\r\n        }\r\n    }\r\n}","InputSystemV2/Infrastructure/UnityPointerInputDriver.cs":"using System;\r\nusing Shield_Shot.InputSystemV2.Application;\r\nusing UnityEngine;\r\nusing UnityEngine.InputSystem.EnhancedTouch;\r\nusing UnityEngine.InputSystem.LowLevel;\r\n\r\nnamespace Shield_Shot.InputSystemV2.Infrastructure\r\n{\r\n    public sealed class UnityPointerInputDriver\r\n        : MonoBehaviour\r\n    {\r\n        private ICancelablePointerSource source;\r\n        private IPointerFrameSink pipeline;\r\n        private bool enhancedTouchRegistered;\r\n\r\n        public bool IsConfigured =\u003e\r\n            source != null \u0026\u0026\r\n            pipeline != null;\r\n\r\n        private void Awake()\r\n        {\r\n            source = new UnityPointerSource();\r\n        }\r\n\r\n        private void OnEnable()\r\n        {\r\n            EnhancedTouchSupport.Enable();\r\n            enhancedTouchRegistered = true;\r\n        }\r\n\r\n        private void Update()\r\n        {\r\n            if (!IsConfigured)\r\n            {\r\n                return;\r\n            }\r\n\r\n            source.Collect(pipeline);\r\n            pipeline.CompleteFrame();\r\n        }\r\n\r\n        private void OnDisable()\r\n        {\r\n            try\r\n            {\r\n                CancelActiveInput();\r\n            }\r\n            finally\r\n            {\r\n                DisableEnhancedTouch();\r\n            }\r\n        }\r\n\r\n        public void SetPipeline(\r\n            IPointerFrameSink pointerPipeline)\r\n        {\r\n            pipeline = pointerPipeline\r\n                ?? throw new ArgumentNullException(\r\n                    nameof(pointerPipeline));\r\n        }\r\n\r\n        private void OnApplicationFocus(\r\n            bool hasFocus)\r\n        {\r\n            if (!hasFocus)\r\n            {\r\n                CancelActiveInput();\r\n            }\r\n        }\r\n\r\n        private void OnApplicationPause(\r\n            bool isPaused)\r\n        {\r\n            if (isPaused)\r\n            {\r\n                CancelActiveInput();\r\n            }\r\n        }\r\n        private void CancelActiveInput()\r\n        {\r\n            if (source == null ||\r\n                pipeline == null)\r\n            {\r\n                return;\r\n            }\r\n\r\n            try\r\n            {\r\n                source.CancelActivePointers(\r\n                    pipeline,\r\n                    InputState.currentTime);\r\n            }\r\n            finally\r\n            {\r\n                pipeline.CompleteFrame();\r\n            }\r\n        }\r\n        private void DisableEnhancedTouch()\r\n        {\r\n            if (!enhancedTouchRegistered)\r\n            {\r\n                return;\r\n            }\r\n\r\n            EnhancedTouchSupport.Disable();\r\n            enhancedTouchRegistered = false;\r\n        }\r\n    }\r\n}","InputSystemV2/Integration/InputSystemV2RuntimeBehaviour.cs":"using Shield_Shot.InputSystemV2.Application;\r\nusing Shield_Shot.InputSystemV2.Combat.Application;\r\nusing Shield_Shot.InputSystemV2.Combat.Domain;\r\nusing Shield_Shot.InputSystemV2.Domain;\r\nusing Shield_Shot.InputSystemV2.Gestures.Application;\r\nusing Shield_Shot.InputSystemV2.Infrastructure;\r\nusing UnityEngine;\r\nusing Unity.Profiling;\r\n\r\nnamespace Shield_Shot.InputSystemV2.Integration\r\n{\r\n    [RequireComponent(typeof(UnityPointerInputDriver))]\r\n    public sealed class InputSystemV2RuntimeBehaviour\r\n        : MonoBehaviour\r\n    {\r\n        [Header(\"Filter\")]\r\n        [SerializeField, Min(0f)]\r\n        private float minimumMovementDistance = 5f;\r\n\r\n        [Header(\"Combat Routing\")]\r\n        [SerializeField]\r\n        private CombatSplitDirection splitDirection =\r\n            CombatSplitDirection.LeftRight;\r\n\r\n        [SerializeField, Range(0.01f, 0.99f)]\r\n        private float splitRatio = 0.5f;\r\n\r\n        [SerializeField]\r\n        private bool isInverted;\r\n\r\n        [SerializeField]\r\n        private Vector2 referenceResolution =\r\n            new Vector2(1080f, 1920f);\r\n\r\n        [Header(\"Attack Charge\")]\r\n        [SerializeField, Range(0f, 1f)]\r\n        private float minimumAimDistanceRatio = 0.05f;\r\n\r\n        [SerializeField, Min(0f)]\r\n        private double chargeStartDelay = 0.15d;\r\n\r\n        [SerializeField, Min(0.01f)]\r\n        private double fullChargeDuration = 1d;\r\n\r\n        [SerializeField, Min(0.001f)]\r\n        private double chargeSignalInterval = 1d / 30d;\r\n\r\n        [Header(\"Gameplay Output\")]\r\n        [SerializeField]\r\n        private WeaponAttackInputAdapter weaponAttackInputAdapter;\r\n        [SerializeField]\r\n        private ShieldDefenseInputAdapter shieldDefenseInputAdapter;\r\n\r\n\r\n        private IPointerFrameSink runtimePipeline;\r\n\r\n        private bool externalInputActive;\r\n        public bool IsExternalInputActive =\u003e\r\n        externalInputActive;\r\n\r\n        private UnityPointerInputDriver driver;\r\n\r\n        private PointerStartBlockFilter viewportBlockFilter;\r\n        private PointerStartBlockFilter uiBlockFilter;\r\n        private PointerMovementThresholdFilter movementFilter;\r\n        private PointerMoveCoalescingSink movementCoalescer;\r\n\r\n        private CombatPointerRouter combatRouter;\r\n        private RuntimeCombatInputLayoutProvider runtimeLayoutProvider;\r\n\r\n        private PointerGestureTracker attackGestureTracker;\r\n        private PointerGestureTracker defenseGestureTracker;\r\n\r\n        private AttackGestureInterpreter attackInterpreter;\r\n        private DefenseGestureInterpreter defenseInterpreter;\r\n\r\n        private static readonly ProfilerMarker\r\n    AttackTickMarker =\r\n        new ProfilerMarker(\r\n            \"Input.V2.AttackTick\");\r\n        public bool IsConfigured\r\n        {\r\n            get;\r\n            private set;\r\n        }\r\n\r\n        private void Awake()\r\n        {\r\n            driver =\r\n                GetComponent\u003cUnityPointerInputDriver\u003e();\r\n            driver.enabled = false;\r\n            BuildPipeline();\r\n        }\r\n\r\n        private void OnEnable()\r\n        {\r\n            externalInputActive = false;\r\n\r\n\r\n            if (driver != null)\r\n            {\r\n                driver.enabled = true;\r\n            }\r\n        }\r\n\r\n        private void LateUpdate()\r\n        {\r\n            if (attackInterpreter == null)\r\n            {\r\n                return;\r\n            }\r\n\r\n            AttackTickMarker.Begin();\r\n\r\n            try\r\n            {\r\n                attackInterpreter.Tick();\r\n            }\r\n            finally\r\n            {\r\n                AttackTickMarker.End();\r\n            }\r\n        }\r\n\r\n        private void OnDisable()\r\n        {\r\n            /*\r\n             * Driver�� ���� ��� Ȱ�� �Է��� Canceled�� ���޵ȴ�.\r\n             * �� ���� �� ����� ���� ���¸� �ʱ�ȭ�Ѵ�.\r\n             */\r\n            if (driver != null \u0026\u0026\r\n                driver.enabled)\r\n            {\r\n                driver.enabled = false;\r\n            }\r\n\r\n            ResetRuntime();\r\n            externalInputActive = false;\r\n        }\r\n\r\n        [ContextMenu(\"Reset Input System V2 Runtime\")]\r\n        public void ResetRuntime()\r\n        {\r\n            viewportBlockFilter?.Reset();\r\n            uiBlockFilter?.Reset();\r\n            movementFilter?.Reset();\r\n            movementCoalescer?.Reset();\r\n\r\n            combatRouter?.Reset();\r\n\r\n            attackGestureTracker?.Reset();\r\n            defenseGestureTracker?.Reset();\r\n\r\n            attackInterpreter?.Reset();\r\n            weaponAttackInputAdapter?.ResetInput();\r\n            shieldDefenseInputAdapter?.ResetInput();\r\n        }\r\n\r\n        private void BuildPipeline()\r\n        {\r\n            IsConfigured = false;\r\n\r\n            Rect fallbackViewport =\r\n                new Rect(\r\n                    0f,\r\n                    0f,\r\n                    referenceResolution.x,\r\n                    referenceResolution.y);\r\n\r\n            IPointerViewportProvider viewportProvider =\r\n                new ScreenPointerViewportProvider(\r\n                    in fallbackViewport);\r\n\r\n            CombatInputLayout initialCombatLayout =\r\n                new CombatInputLayout(\r\n                    splitDirection,\r\n                    splitRatio,\r\n                    isInverted);\r\n\r\n            runtimeLayoutProvider =\r\n                new RuntimeCombatInputLayoutProvider(\r\n                    in initialCombatLayout);\r\n\r\n            ICombatInputLayoutProvider layoutProvider =\r\n                runtimeLayoutProvider;\r\n\r\n            ICombatInputChannelResolver channelResolver =\r\n                new SplitCombatInputChannelResolver(\r\n                    layoutProvider,\r\n                    viewportProvider);\r\n\r\n            AttackChargeSettings chargeSettings =\r\n                new AttackChargeSettings(\r\n                    minimumAimDistanceRatio,\r\n                    chargeStartDelay,\r\n                    fullChargeDuration,\r\n                    chargeSignalInterval);\r\n\r\n            IAttackChargeSettingsProvider\r\n                chargeSettingsProvider =\r\n                    new FixedAttackChargeSettingsProvider(\r\n                        in chargeSettings);\r\n\r\n            IInputClock inputClock =\r\n                new UnityInputClock();\r\n\r\n            IAttackInputSink attackOutput =\r\n                weaponAttackInputAdapter;\r\n\r\n            if (attackOutput == null)\r\n            {\r\n                Debug.LogError(\r\n                    \"WeaponAttackInputAdapter is not assigned.\",\r\n                    this);\r\n\r\n                enabled = false;\r\n                return;\r\n            }\r\n\r\n            IDefenseInputSink defenseOutput =\r\n                shieldDefenseInputAdapter;\r\n\r\n            if (defenseOutput == null)\r\n            {\r\n                Debug.LogError(\r\n                    \"ShieldDefenseInputAdapter is not assigned.\",\r\n                    this);\r\n\r\n                enabled = false;\r\n                return;\r\n            }\r\n\r\n            attackInterpreter =\r\n                new AttackGestureInterpreter(\r\n                    chargeSettingsProvider,\r\n                    viewportProvider,\r\n                    inputClock,\r\n                    attackOutput);\r\n\r\n            attackGestureTracker =\r\n                new PointerGestureTracker(\r\n                    attackInterpreter);\r\n\r\n            defenseInterpreter =\r\n                new DefenseGestureInterpreter(\r\n                    defenseOutput);\r\n\r\n            defenseGestureTracker =\r\n                new PointerGestureTracker(\r\n                    defenseInterpreter);\r\n\r\n            combatRouter =\r\n                new CombatPointerRouter(\r\n                    channelResolver,\r\n                    attackGestureTracker,\r\n                    defenseGestureTracker);\r\n\r\n            movementFilter =\r\n                new PointerMovementThresholdFilter(\r\n                    minimumMovementDistance);\r\n\r\n            IPointerSampleSink movementFilteredPipeline =\r\n                new FilteredPointerSink(\r\n                    movementFilter,\r\n                    combatRouter);\r\n\r\n            movementCoalescer =\r\n                new PointerMoveCoalescingSink(\r\n                    movementFilteredPipeline);\r\n\r\n            IPointerStartBlockPolicy uiBlockPolicy =\r\n                new EventSystemPointerStartBlockPolicy();\r\n\r\n            uiBlockFilter =\r\n                new PointerStartBlockFilter(\r\n                    uiBlockPolicy);\r\n\r\n            IPointerFrameSink uiFilteredPipeline =\r\n                new FilteredPointerFrameSink(\r\n                    uiBlockFilter,\r\n                    movementCoalescer);\r\n\r\n            IPointerStartBlockPolicy viewportBlockPolicy =\r\n                new ViewportPointerStartBlockPolicy(\r\n                    viewportProvider);\r\n\r\n            viewportBlockFilter =\r\n                new PointerStartBlockFilter(\r\n                    viewportBlockPolicy);\r\n\r\n            runtimePipeline =\r\n                new FilteredPointerFrameSink(\r\n                    viewportBlockFilter,\r\n                    uiFilteredPipeline);\r\n\r\n            driver.SetPipeline(\r\n                runtimePipeline);\r\n\r\n            IsConfigured = true;\r\n        }\r\n        public void BeginExternalInput()\r\n        {\r\n            if (!IsConfigured ||\r\n                runtimePipeline == null)\r\n            {\r\n                throw new System.InvalidOperationException(\r\n                    \"Input System V2 Runtime is not configured.\");\r\n            }\r\n\r\n            /*\r\n             * ���� Unity �Է� ������ �ߴ��Ѵ�.\r\n             * Runtime Behaviour�� Ȱ�� ���·� ����\r\n             * AttackGestureInterpreter.Tick()�� ��� �����Ѵ�.\r\n             */\r\n            if (driver != null \u0026\u0026\r\n                driver.enabled)\r\n            {\r\n                driver.enabled = false;\r\n            }\r\n\r\n            ResetRuntime();\r\n            externalInputActive = true;\r\n        }\r\n\r\n        public void SubmitExternalSample(\r\n            in PointerSample sample)\r\n        {\r\n            if (!externalInputActive)\r\n            {\r\n                throw new System.InvalidOperationException(\r\n                    \"BeginExternalInput must be called first.\");\r\n            }\r\n\r\n            runtimePipeline.Receive(\r\n                in sample);\r\n        }\r\n\r\n        public void CompleteExternalFrame()\r\n        {\r\n            if (!externalInputActive)\r\n            {\r\n                throw new System.InvalidOperationException(\r\n                    \"BeginExternalInput must be called first.\");\r\n            }\r\n\r\n            runtimePipeline.CompleteFrame();\r\n        }\r\n\r\n        public void EndExternalInput()\r\n        {\r\n            if (!externalInputActive)\r\n            {\r\n                return;\r\n            }\r\n\r\n            runtimePipeline.CompleteFrame();\r\n            ResetRuntime();\r\n\r\n            externalInputActive = false;\r\n        }\r\n\r\n        public void ResumeLiveInput()\r\n        {\r\n            EndExternalInput();\r\n\r\n            if (driver != null)\r\n            {\r\n                driver.enabled = true;\r\n            }\r\n        }\r\n\r\n        public void ApplyCombatLayout(\r\n    in CombatInputLayout layout)\r\n        {\r\n            /*\r\n             * Inspector�� ���� �����Ϳ��� ���� ���밪�� �����.\r\n             */\r\n            splitDirection = layout.SplitDirection;\r\n            splitRatio = layout.SplitRatio;\r\n            isInverted = layout.IsInverted;\r\n\r\n            /*\r\n             * Awake ������ ȣ��ƴٸ� serialized field�� �����Ѵ�.\r\n             * ���� BuildPipeline���� �ش� ������ Provider�� �����ȴ�.\r\n             */\r\n            runtimeLayoutProvider?.Apply(\r\n                in layout);\r\n        }\r\n\r\n        [ContextMenu(\"Apply Inspector Combat Layout\")]\r\n        private void ApplyInspectorCombatLayout()\r\n        {\r\n            var layout =\r\n                new CombatInputLayout(\r\n                    splitDirection,\r\n                    splitRatio,\r\n                    isInverted);\r\n\r\n            ApplyCombatLayout(\r\n                in layout);\r\n        }\r\n    }\r\n}","InputSystemV2/Integration/ShieldDefenseInputAdapter.cs":"using Shield_Shot.GameplayCore.Weapon;\r\nusing Shield_Shot.GameplayCore.Weapon.Shield;\r\nusing Shield_Shot.InputSystemV2.Combat.Application;\r\nusing Shield_Shot.InputSystemV2.Combat.Domain;\r\nusing Shield_Shot.InputSystemV2.Domain;\r\nusing UnityEngine;\r\n\r\nnamespace Shield_Shot.InputSystemV2.Integration\r\n{\r\n    public sealed class ShieldDefenseInputAdapter\r\n        : MonoBehaviour,\r\n          IDefenseInputSink\r\n    {\r\n        [SerializeField]\r\n        private WeaponManager weaponManager;\r\n\r\n        private bool hasActivePointer;\r\n        private PointerKey activePointer;\r\n\r\n        private ShieldOrbitController activeOrbitController;\r\n\r\n        public void Receive(\r\n            in DefenseInputSample sample)\r\n        {\r\n            switch (sample.Phase)\r\n            {\r\n                case DefenseInputPhase.Began:\r\n                    Begin(in sample);\r\n                    break;\r\n\r\n                case DefenseInputPhase.DirectionChanged:\r\n                    ApplyDirection(in sample);\r\n                    break;\r\n\r\n                case DefenseInputPhase.Released:\r\n                case DefenseInputPhase.Canceled:\r\n                    End(sample.Pointer);\r\n                    break;\r\n            }\r\n        }\r\n\r\n        public void ResetInput()\r\n        {\r\n            hasActivePointer = false;\r\n            activePointer = default;\r\n            activeOrbitController = null;\r\n        }\r\n\r\n        private void OnDisable()\r\n        {\r\n            ResetInput();\r\n        }\r\n\r\n        private void Begin(\r\n            in DefenseInputSample sample)\r\n        {\r\n            if (hasActivePointer ||\r\n                weaponManager == null)\r\n            {\r\n                return;\r\n            }\r\n\r\n            SkillShield currentShield =\r\n                weaponManager.CurrentShield;\r\n\r\n            ShieldOrbitController orbitController =\r\n                currentShield != null\r\n                    ? currentShield.OrbitController\r\n                    : null;\r\n\r\n            if (orbitController == null)\r\n            {\r\n                return;\r\n            }\r\n\r\n            activePointer = sample.Pointer;\r\n            activeOrbitController = orbitController;\r\n            hasActivePointer = true;\r\n\r\n            activeOrbitController.ResetDragOrigin();\r\n        }\r\n\r\n        private void ApplyDirection(\r\n            in DefenseInputSample sample)\r\n        {\r\n            if (!IsActivePointer(sample.Pointer) ||\r\n                activeOrbitController == null)\r\n            {\r\n                return;\r\n            }\r\n\r\n            activeOrbitController.UpdateOrbitFromDrag(\r\n                sample.Displacement);\r\n        }\r\n\r\n        private void End(\r\n            PointerKey pointer)\r\n        {\r\n            if (!IsActivePointer(pointer))\r\n            {\r\n                return;\r\n            }\r\n\r\n            ResetInput();\r\n        }\r\n\r\n        private bool IsActivePointer(\r\n            PointerKey pointer)\r\n        {\r\n            return\r\n                hasActivePointer \u0026\u0026\r\n                activePointer == pointer;\r\n        }\r\n    }\r\n}","InputSystemV2/Integration/WeaponAttackInputAdapter.cs":"using System.Collections.Generic;\nusing Shield_Shot.GameplayCore.Augment;\nusing Shield_Shot.GameplayCore.Weapon;\nusing Shield_Shot.GameplayCore.Weapon.Core;\nusing Shield_Shot.InputSystem.Data;\r\nusing Shield_Shot.InputSystemV2.Combat.Application;\r\nusing Shield_Shot.InputSystemV2.Combat.Domain;\r\nusing Shield_Shot.InputSystemV2.Domain;\r\nusing UnityEngine;\r\n\r\nnamespace Shield_Shot.InputSystemV2.Integration\r\n{\r\n    public sealed class WeaponAttackInputAdapter\r\n        : MonoBehaviour, IAttackInputSink\r\n    {\r\n        [SerializeField]\r\n        private WeaponManager weaponManager;\r\n\r\n        private readonly Dictionary\u003cPointerKey, ActiveWeaponInput\u003e\r\n            activeInputs =\r\n                new Dictionary\u003cPointerKey, ActiveWeaponInput\u003e(2);\r\n\r\n        public void Receive(\r\n            in AttackInputSample sample)\r\n        {\r\n            switch (sample.Phase)\r\n            {\r\n                case AttackInputPhase.Began:\r\n                    Begin(in sample);\r\n                    break;\r\n\r\n                case AttackInputPhase.AimChanged:\r\n                case AttackInputPhase.ChargeChanged:\r\n                    ApplyState(in sample);\r\n                    break;\r\n\r\n                case AttackInputPhase.Released:\r\n                    Release(in sample);\r\n                    break;\r\n\r\n                case AttackInputPhase.Canceled:\r\n                    Cancel(sample.Pointer);\r\n                    break;\r\n            }\r\n        }\r\n\r\n        public void ResetInput()\n        {\n            foreach (KeyValuePair\u003cPointerKey, ActiveWeaponInput\u003e entry\r\n                     in activeInputs)\r\n            {\r\n                entry.Value.Weapon?.Deactivate();\r\n            }\r\n\r\n            activeInputs.Clear();\n        }\n\n        private void Update()\n        {\n            if (AugmentPopupUI.IsOpen ||\n                Time.timeScale \u003c= 0f)\n            {\n                return;\n            }\n\n            foreach (KeyValuePair\u003cPointerKey, ActiveWeaponInput\u003e entry\n                     in activeInputs)\n            {\n                ActiveWeaponInput activeInput = entry.Value;\n                WeaponBase weapon = activeInput.Weapon;\n\n                if (weapon == null ||\n                    weapon.Type != WeaponType.Rifle)\n                {\n                    continue;\n                }\n\n                activeInput.ElapsedTime += Time.unscaledDeltaTime;\n                weapon.HandleInputStay(\n                    CreateLegacyStayContext(\n                        entry.Key,\n                        activeInput));\n            }\n        }\n\n        private void OnDisable()\n        {\n            ResetInput();\n        }\r\n\r\n        private void Begin(\r\n            in AttackInputSample sample)\r\n        {\r\n            if (weaponManager == null)\r\n            {\r\n                return;\r\n            }\r\n\r\n            if (activeInputs.TryGetValue(\r\n                    sample.Pointer,\r\n                    out ActiveWeaponInput previousInput))\r\n            {\r\n                previousInput.Weapon?.Deactivate();\r\n                activeInputs.Remove(sample.Pointer);\r\n            }\r\n\r\n            WeaponBase weapon =\r\n                weaponManager.CurrentWeapon;\r\n\r\n            if (weapon == null)\r\n            {\r\n                return;\r\n            }\r\n\r\n            ActiveWeaponInput activeInput =\n                new ActiveWeaponInput(\n                    weapon,\n                    sample.Timestamp);\n            activeInput.UpdateState(in sample);\n\n            activeInputs.Add(\n                sample.Pointer,\n                activeInput);\r\n\r\n            weapon.ApplyAttackInputState(\r\n                sample.AimVector,\r\n                sample.ChargeRatio);\r\n        }\r\n\r\n        private void ApplyState(\r\n            in AttackInputSample sample)\r\n        {\r\n            if (!activeInputs.TryGetValue(\r\n                    sample.Pointer,\r\n                    out ActiveWeaponInput activeInput))\r\n            {\r\n                return;\r\n            }\r\n\r\n            activeInput.Weapon.ApplyAttackInputState(\n                sample.AimVector,\n                sample.ChargeRatio);\n\n            activeInput.UpdateState(in sample);\n        }\n\r\n        private void Release(\r\n            in AttackInputSample sample)\r\n        {\r\n            if (!activeInputs.TryGetValue(\r\n                    sample.Pointer,\r\n                    out ActiveWeaponInput activeInput))\r\n            {\r\n                return;\r\n            }\r\n\r\n            activeInputs.Remove(\r\n                sample.Pointer);\r\n\r\n            WeaponBase weapon =\r\n                activeInput.Weapon;\r\n\r\n            if (weapon == null)\r\n            {\r\n                return;\r\n            }\r\n\r\n            weapon.ApplyAttackInputState(\r\n                sample.AimVector,\r\n                sample.ChargeRatio);\r\n\r\n            if (weapon.Type == WeaponType.Bow \u0026\u0026\r\n                !sample.IsAimEligible)\r\n            {\r\n                weapon.Deactivate();\r\n                return;\r\n            }\r\n\r\n            InputContext legacyContext =\r\n                CreateLegacyReleaseContext(\r\n                    in sample,\r\n                    activeInput.StartTimestamp);\r\n\r\n            weapon.HandleInputUp(\r\n                legacyContext);\r\n        }\r\n\r\n        private void Cancel(\r\n            PointerKey pointer)\r\n        {\r\n            if (!activeInputs.TryGetValue(\r\n                    pointer,\r\n                    out ActiveWeaponInput activeInput))\r\n            {\r\n                return;\r\n            }\r\n\r\n            activeInputs.Remove(pointer);\r\n            activeInput.Weapon?.Deactivate();\r\n        }\r\n\r\n        private static InputContext CreateLegacyReleaseContext(\n            in AttackInputSample sample,\n            double startTimestamp)\n        {\r\n            return new InputContext\r\n            {\r\n                fingerId =\r\n                    sample.Pointer.PointerId,\r\n\r\n                state =\r\n                    ConvertChargeState(\r\n                        sample.ChargeState),\r\n\r\n                holdTime =\r\n                    Mathf.Max(\r\n                        0f,\r\n                        (float)(\r\n                            sample.Timestamp -\r\n                            startTimestamp)),\r\n\r\n                dragVector =\r\n                    sample.AimVector,\r\n\r\n                totalDistance =\r\n                    sample.AimVector.magnitude\r\n            };\n        }\n\n        private static InputContext CreateLegacyStayContext(\n            PointerKey pointer,\n            ActiveWeaponInput activeInput)\n        {\n            return new InputContext\n            {\n                fingerId = pointer.PointerId,\n                state = ConvertChargeState(\n                    activeInput.ChargeState),\n                holdTime = activeInput.ElapsedTime,\n                dragVector = activeInput.AimVector,\n                totalDistance =\n                    activeInput.AimVector.magnitude\n            };\n        }\n\n        private static GestureState ConvertChargeState(\r\n            AttackChargeState chargeState)\r\n        {\r\n            switch (chargeState)\r\n            {\r\n                case AttackChargeState.Charging:\r\n                    return GestureState.Charging;\r\n\r\n                case AttackChargeState.FullyCharged:\r\n                    return GestureState.ChargedComplete;\r\n\r\n                default:\r\n                    return GestureState.Released;\r\n            }\r\n        }\r\n\r\n        private sealed class ActiveWeaponInput\n        {\n            public WeaponBase Weapon { get; }\n            public double StartTimestamp { get; }\n            public Vector2 AimVector { get; private set; }\n            public float ChargeRatio { get; private set; }\n            public AttackChargeState ChargeState { get; private set; }\n            public float ElapsedTime { get; set; }\n\n            public ActiveWeaponInput(\n                WeaponBase weapon,\n                double startTimestamp)\n            {\n                Weapon = weapon;\n                StartTimestamp = startTimestamp;\n                AimVector = Vector2.zero;\n                ChargeRatio = 0f;\n                ChargeState = AttackChargeState.Aiming;\n                ElapsedTime = 0f;\n            }\n\n            public void UpdateState(\n                in AttackInputSample sample)\n            {\n                AimVector = sample.AimVector;\n                ChargeRatio = sample.ChargeRatio;\n                ChargeState = sample.ChargeState;\n            }\n        }\n    }\r\n}\n","Performance/InputComparison/BenchmarkPointerSequencePlayer.cs":"using System;\r\nusing UnityEngine;\r\nusing UnityEngine.InputSystem.LowLevel;\r\n\r\nnamespace Shield_Shot.Performance.InputComparison\r\n{\r\n    public sealed class BenchmarkPointerSequencePlayer\r\n        : MonoBehaviour\r\n    {\r\n        private BenchmarkPointerSequence sequence;\r\n        private IBenchmarkPointerInputTarget target;\r\n\r\n        private Vector2 viewportSize;\r\n\r\n        private double startTimestamp;\r\n        private int nextSampleIndex;\r\n\r\n        public bool IsPlaying\r\n        {\r\n            get;\r\n            private set;\r\n        }\r\n\r\n        public int ProcessedSampleCount =\u003e\r\n            nextSampleIndex;\r\n\r\n        public int TotalSampleCount =\u003e\r\n            sequence != null\r\n                ? sequence.Count\r\n                : 0;\r\n\r\n        public float Progress\r\n        {\r\n            get\r\n            {\r\n                if (sequence == null ||\r\n                    sequence.Count == 0)\r\n                {\r\n                    return 0f;\r\n                }\r\n\r\n                return Mathf.Clamp01(\r\n                    (float)nextSampleIndex /\r\n                    sequence.Count);\r\n            }\r\n        }\r\n\r\n        public event Action\u003cBenchmarkPointerSequence\u003e\r\n            SequenceCompleted;\r\n\r\n        public void Play(\r\n            BenchmarkPointerSequence sequence,\r\n            IBenchmarkPointerInputTarget target,\r\n            Vector2 viewportSize)\r\n        {\r\n            if (IsPlaying)\r\n            {\r\n                throw new InvalidOperationException(\r\n                    \"A benchmark sequence is already playing.\");\r\n            }\r\n\r\n            this.sequence =\r\n                sequence\r\n                ?? throw new ArgumentNullException(\r\n                    nameof(sequence));\r\n\r\n            this.target =\r\n                target\r\n                ?? throw new ArgumentNullException(\r\n                    nameof(target));\r\n\r\n            ValidateViewportSize(\r\n                viewportSize);\r\n\r\n            this.viewportSize =\r\n                viewportSize;\r\n\r\n            startTimestamp =\r\n                InputState.currentTime;\r\n\r\n            nextSampleIndex = 0;\r\n\r\n            this.target.BeginSequence(\r\n                viewportSize,\r\n                startTimestamp);\r\n\r\n            IsPlaying = true;\r\n        }\r\n\r\n        public void Stop()\r\n        {\r\n            if (!IsPlaying)\r\n            {\r\n                return;\r\n            }\r\n\r\n            EndPlayback(\r\n                notifyCompletion: false);\r\n        }\r\n\r\n        private void Update()\r\n        {\r\n            if (!IsPlaying)\r\n            {\r\n                return;\r\n            }\r\n\r\n            try\r\n            {\r\n                ProcessCurrentFrame();\r\n            }\r\n            catch\r\n            {\r\n                EndPlayback(\r\n                    notifyCompletion: false);\r\n\r\n                throw;\r\n            }\r\n        }\r\n\r\n        private void OnDisable()\r\n        {\r\n            Stop();\r\n        }\r\n\r\n        private void ProcessCurrentFrame()\r\n        {\r\n            double currentTimestamp =\r\n                InputState.currentTime;\r\n\r\n            double elapsed =\r\n                Math.Max(\r\n                    0d,\r\n                    currentTimestamp -\r\n                    startTimestamp);\r\n\r\n            while (nextSampleIndex \u003c\r\n                   sequence.Count)\r\n            {\r\n                BenchmarkPointerSample sample =\r\n                    sequence[nextSampleIndex];\r\n\r\n                if (sample.TimestampOffset \u003e\r\n                    elapsed)\r\n                {\r\n                    break;\r\n                }\r\n\r\n                target.Receive(\r\n                    in sample);\r\n\r\n                nextSampleIndex++;\r\n            }\r\n\r\n            /*\r\n             * �̹� Unity Frame�� ���� ��� Sample��\r\n             * ������ �� ������ ���Ḧ �˸���.\r\n             *\r\n             * V1: ���� �۾� ����\r\n             * V2: ���� �������� Moved Sample ���� �� ����\r\n             */\r\n            target.CompleteFrame();\r\n\r\n            if (nextSampleIndex \u003e=\r\n                sequence.Count)\r\n            {\r\n                EndPlayback(\r\n                    notifyCompletion: true);\r\n            }\r\n        }\r\n\r\n        private void EndPlayback(\r\n            bool notifyCompletion)\r\n        {\r\n            BenchmarkPointerSequence\r\n                completedSequence =\r\n                    sequence;\r\n\r\n            try\r\n            {\r\n                target?.EndSequence();\r\n            }\r\n            finally\r\n            {\r\n                IsPlaying = false;\r\n\r\n                sequence = null;\r\n                target = null;\r\n\r\n                viewportSize = Vector2.zero;\r\n                startTimestamp = 0d;\r\n                nextSampleIndex = 0;\r\n            }\r\n\r\n            if (notifyCompletion \u0026\u0026\r\n                completedSequence != null)\r\n            {\r\n                SequenceCompleted?.Invoke(\r\n                    completedSequence);\r\n            }\r\n        }\r\n\r\n        private static void ValidateViewportSize(\r\n            Vector2 size)\r\n        {\r\n            if (!IsFinite(size.x) ||\r\n                !IsFinite(size.y) ||\r\n                size.x \u003c= 0f ||\r\n                size.y \u003c= 0f)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(size),\r\n                    size,\r\n                    \"Viewport size must be finite \" +\r\n                    \"and positive.\");\r\n            }\r\n        }\r\n\r\n        private static bool IsFinite(float value)\r\n        {\r\n            return\r\n                !float.IsNaN(value) \u0026\u0026\r\n                !float.IsInfinity(value);\r\n        }\r\n    }\r\n}","Performance/InputComparison/InputComparisonBatchStatistics.cs":"using System;\nusing System.Collections.Generic;\n\nnamespace Shield_Shot.Performance.InputComparison\n{\n    public sealed class InputComparisonBatchStatistics\n    {\n        public BenchmarkInputVersion Version { get; }\n        public int RunCount { get; }\n        public IReadOnlyList\u003cInputComparisonMetricStatistics\u003e Metrics { get; }\n        public double AverageMarkerTotalMilliseconds { get; }\n        public double MedianMarkerTotalMilliseconds { get; }\n        public double P95MarkerTotalMilliseconds { get; }\n        public double MaximumMarkerTotalMilliseconds { get; }\n\n        private InputComparisonBatchStatistics(\n            BenchmarkInputVersion version,\n            int runCount,\n            IReadOnlyList\u003cInputComparisonMetricStatistics\u003e metrics,\n            NumericStatistics markerTotals)\n        {\n            Version = version;\n            RunCount = runCount;\n            Metrics = metrics;\n            AverageMarkerTotalMilliseconds = markerTotals.Average;\n            MedianMarkerTotalMilliseconds = markerTotals.Median;\n            P95MarkerTotalMilliseconds = markerTotals.P95;\n            MaximumMarkerTotalMilliseconds = markerTotals.Maximum;\n        }\n\n        public static InputComparisonBatchStatistics Create(\n            BenchmarkInputVersion version,\n            IReadOnlyList\u003cInputComparisonRunResult\u003e runs)\n        {\n            var valuesByMarker =\n                new Dictionary\u003cstring, List\u003cdouble\u003e\u003e();\n            var callsByMarker =\n                new Dictionary\u003cstring, long\u003e();\n            var markerTotals = new List\u003cdouble\u003e(runs.Count);\n\n            for (int runIndex = 0; runIndex \u003c runs.Count; runIndex++)\n            {\n                InputComparisonRunResult run = runs[runIndex];\n\n                if (run.Version != version)\n                {\n                    throw new ArgumentException(\n                        \"All runs must use the requested input version.\",\n                        nameof(runs));\n                }\n\n                markerTotals.Add(run.MarkerTotalMilliseconds);\n\n                for (int metricIndex = 0;\n                     metricIndex \u003c run.Metrics.Count;\n                     metricIndex++)\n                {\n                    ProfilerMetricSummary metric =\n                        run.Metrics[metricIndex];\n\n                    if (!valuesByMarker.TryGetValue(\n                            metric.MarkerName,\n                            out List\u003cdouble\u003e values))\n                    {\n                        values = new List\u003cdouble\u003e(runs.Count);\n                        valuesByMarker.Add(metric.MarkerName, values);\n                        callsByMarker.Add(metric.MarkerName, 0);\n                    }\n\n                    values.Add(metric.TotalMilliseconds);\n                    callsByMarker[metric.MarkerName] +=\n                        metric.TotalCallCount;\n                }\n            }\n\n            var metricStatistics =\n                new List\u003cInputComparisonMetricStatistics\u003e(\n                    valuesByMarker.Count);\n\n            foreach (\n                KeyValuePair\u003cstring, List\u003cdouble\u003e\u003e pair\n                in valuesByMarker)\n            {\n                NumericStatistics values =\n                    NumericStatistics.Create(pair.Value);\n\n                metricStatistics.Add(\n                    new InputComparisonMetricStatistics(\n                        pair.Key,\n                        callsByMarker[pair.Key],\n                        values));\n            }\n\n            metricStatistics.Sort(\n                (left, right) =\u003e\n                    string.CompareOrdinal(\n                        left.MarkerName,\n                        right.MarkerName));\n\n            return new InputComparisonBatchStatistics(\n                version,\n                runs.Count,\n                metricStatistics,\n                NumericStatistics.Create(markerTotals));\n        }\n\n        public sealed class InputComparisonMetricStatistics\n        {\n            public string MarkerName { get; }\n            public long TotalCallCount { get; }\n            public double AverageTotalMilliseconds { get; }\n            public double MedianTotalMilliseconds { get; }\n            public double P95TotalMilliseconds { get; }\n            public double MaximumTotalMilliseconds { get; }\n\n            internal InputComparisonMetricStatistics(\n                string markerName,\n                long totalCallCount,\n                NumericStatistics statistics)\n            {\n                MarkerName = markerName;\n                TotalCallCount = totalCallCount;\n                AverageTotalMilliseconds = statistics.Average;\n                MedianTotalMilliseconds = statistics.Median;\n                P95TotalMilliseconds = statistics.P95;\n                MaximumTotalMilliseconds = statistics.Maximum;\n            }\n        }\n\n        internal readonly struct NumericStatistics\n        {\n            public double Average { get; }\n            public double Median { get; }\n            public double P95 { get; }\n            public double Maximum { get; }\n\n            private NumericStatistics(\n                double average,\n                double median,\n                double p95,\n                double maximum)\n            {\n                Average = average;\n                Median = median;\n                P95 = p95;\n                Maximum = maximum;\n            }\n\n            public static NumericStatistics Create(\n                IReadOnlyList\u003cdouble\u003e source)\n            {\n                if (source.Count == 0)\n                {\n                    return new NumericStatistics(0d, 0d, 0d, 0d);\n                }\n\n                var sorted = new List\u003cdouble\u003e(source.Count);\n                double total = 0d;\n\n                for (int index = 0; index \u003c source.Count; index++)\n                {\n                    double value = source[index];\n                    sorted.Add(value);\n                    total += value;\n                }\n\n                sorted.Sort();\n\n                int middle = sorted.Count / 2;\n                double median =\n                    (sorted.Count \u0026 1) == 1\n                        ? sorted[middle]\n                        : (sorted[middle - 1] + sorted[middle]) * 0.5d;\n\n                double p95Position =\n                    (sorted.Count - 1) * 0.95d;\n                int p95LowerIndex =\n                    (int)Math.Floor(p95Position);\n                int p95UpperIndex =\n                    (int)Math.Ceiling(p95Position);\n                double p95Blend =\n                    p95Position - p95LowerIndex;\n                double p95 =\n                    sorted[p95LowerIndex] +\n                    (sorted[p95UpperIndex] -\n                     sorted[p95LowerIndex]) *\n                    p95Blend;\n\n                return new NumericStatistics(\n                    total / sorted.Count,\n                    median,\n                    p95,\n                    sorted[sorted.Count - 1]);\n            }\n        }\n    }\n}\n","Performance/InputComparison/InputComparisonBuildRunner.cs":"using System;\nusing System.Collections;\nusing UnityEngine;\n\nnamespace Shield_Shot.Performance.InputComparison\n{\n    public sealed class InputComparisonBuildRunner : MonoBehaviour\n    {\n        [SerializeField]\n        private InputComparisonSmokeTestBehaviour smokeTest;\n\n        [Header(\"Automatic Run\")]\n        [SerializeField]\n        private bool runOnlyInDevelopmentBuild = true;\n\n        [SerializeField]\n        private bool autoRunInEditor;\n\n        [SerializeField, Min(0f)]\n        private float startupDelaySeconds = 3f;\n\n        [Header(\"Benchmark Frame Pacing\")]\n        [SerializeField, Min(1)]\n        private int benchmarkTargetFrameRate = 60;\n\n        [SerializeField]\n        private bool disableVSyncDuringBenchmark = true;\n\n        private readonly InputComparisonDeviceInfoProvider\n            deviceInfoProvider = new();\n\n        private IInputComparisonResultWriter resultWriter;\n        private Coroutine startupCoroutine;\n        private bool hasStarted;\n        private bool framePacingApplied;\n        private int previousTargetFrameRate;\n        private int previousVSyncCount;\n\n        private void Awake()\n        {\n            resultWriter = new JsonInputComparisonResultWriter();\n        }\n\n        private void OnEnable()\n        {\n            if (smokeTest != null)\n            {\n                smokeTest.BatchComparisonCompleted +=\n                    HandleBatchComparisonCompleted;\n            }\n\n            startupCoroutine =\n                StartCoroutine(StartBenchmarkWhenReady());\n        }\n\n        private void OnDisable()\n        {\n            if (smokeTest != null)\n            {\n                smokeTest.BatchComparisonCompleted -=\n                    HandleBatchComparisonCompleted;\n            }\n\n            if (startupCoroutine != null)\n            {\n                StopCoroutine(startupCoroutine);\n                startupCoroutine = null;\n            }\n\n            RestoreFramePacing();\n        }\n\n        private IEnumerator StartBenchmarkWhenReady()\n        {\n#if UNITY_EDITOR\n            if (!autoRunInEditor)\n            {\n                yield break;\n            }\n#endif\n\n            if (runOnlyInDevelopmentBuild \u0026\u0026\n                !Debug.isDebugBuild)\n            {\n                Debug.LogWarning(\n                    \"[Input Build Benchmark] Skipped | \" +\n                    \"This player is not a Development Build. \" +\n                    \"Enable Development Build in Build Profiles \" +\n                    \"or disable Run Only In Development Build.\",\n                    this);\n                yield break;\n            }\n\n            if (hasStarted)\n            {\n                yield break;\n            }\n\n            if (smokeTest == null)\n            {\n                Debug.LogError(\n                    \"InputComparisonSmokeTestBehaviour is not assigned.\",\n                    this);\n                yield break;\n            }\n\n            if (startupDelaySeconds \u003e 0f)\n            {\n                yield return new WaitForSecondsRealtime(\n                    startupDelaySeconds);\n            }\n\n            ApplyBenchmarkFramePacing();\n\n            double estimatedSeconds =\n                smokeTest.DurationSeconds *\n                (smokeTest.BatchWarmupRuns +\n                 smokeTest.BatchMeasuredRuns) *\n                2d;\n\n            Debug.Log(\n                $\"[Input Build Benchmark] Starting | \" +\n                $\"Estimated Duration: {estimatedSeconds:F0}s | \" +\n                $\"The benchmark runs without progress logs.\",\n                this);\n\n            hasStarted = smokeTest.TryRunBatchComparison(\n                emitProgressLogs: false);\n\n            if (!hasStarted)\n            {\n                RestoreFramePacing();\n\n                Debug.LogError(\n                    \"Input comparison benchmark could not start.\",\n                    this);\n            }\n\n            startupCoroutine = null;\n        }\n\n        private void HandleBatchComparisonCompleted(\n            InputComparisonBatchResult result)\n        {\n            try\n            {\n                InputComparisonResultDocument document =\n                    InputComparisonResultDocument.Create(\n                        result,\n                        smokeTest,\n                        deviceInfoProvider);\n                string filePath = resultWriter.Write(document);\n\n                /*\n                 * This single post-measurement log does not contaminate\n                 * the recorded benchmark interval.\n                 */\n                Debug.Log(\n                    $\"[Input Build Benchmark] Completed | \" +\n                    $\"Result: {filePath}\",\n                    this);\n            }\n            catch (Exception exception)\n            {\n                Debug.LogException(exception, this);\n            }\n            finally\n            {\n                RestoreFramePacing();\n            }\n        }\n\n        private void ApplyBenchmarkFramePacing()\n        {\n            if (framePacingApplied)\n            {\n                return;\n            }\n\n            previousTargetFrameRate =\n                Application.targetFrameRate;\n            previousVSyncCount =\n                QualitySettings.vSyncCount;\n\n            if (disableVSyncDuringBenchmark)\n            {\n                QualitySettings.vSyncCount = 0;\n            }\n\n            Application.targetFrameRate =\n                Mathf.Max(1, benchmarkTargetFrameRate);\n\n            framePacingApplied = true;\n        }\n\n        private void RestoreFramePacing()\n        {\n            if (!framePacingApplied)\n            {\n                return;\n            }\n\n            Application.targetFrameRate =\n                previousTargetFrameRate;\n            QualitySettings.vSyncCount =\n                previousVSyncCount;\n\n            framePacingApplied = false;\n        }\n    }\n}\n","Performance/InputComparison/InputProfilerRecorderSession.cs":"using System;\nusing System.Collections.Generic;\nusing Unity.Profiling;\n\nnamespace Shield_Shot.Performance.InputComparison\n{\n    public sealed class InputProfilerRecorderSession : IDisposable\n    {\n        private readonly List\u003cMetricRecorder\u003e recorders = new();\n\n        public void Start(BenchmarkInputVersion version, int capacity)\n        {\n            Dispose();\n            int safeCapacity = Math.Max(1, capacity);\n\n            switch (version)\n            {\n                case BenchmarkInputVersion.V1:\n                    AddRecorder(\"Input.V1.ProcessSamples\", safeCapacity);\n                    AddRecorder(\"Input.V1.GestureUpdate\", safeCapacity);\n                    break;\n                case BenchmarkInputVersion.V2:\n                    AddRecorder(\"Input.V2.ProcessSamples\", safeCapacity);\n                    AddRecorder(\"Input.V2.CompleteFrame\", safeCapacity);\n                    AddRecorder(\"Input.V2.AttackTick\", safeCapacity);\n                    break;\n                default:\n                    throw new ArgumentOutOfRangeException(\n                        nameof(version),\n                        version,\n                        \"Unsupported input version.\");\n            }\n        }\n\n        public IReadOnlyList\u003cProfilerMetricSummary\u003e StopAndCollect()\n        {\n            var summaries =\n                new List\u003cProfilerMetricSummary\u003e(recorders.Count);\n\n            foreach (MetricRecorder metricRecorder in recorders)\n            {\n                metricRecorder.Recorder.Stop();\n                summaries.Add(\n                    ProfilerMetricSummary.Create(\n                        metricRecorder.MarkerName,\n                        metricRecorder.Recorder));\n            }\n\n            Dispose();\n            return summaries;\n        }\n\n        public void Dispose()\n        {\n            foreach (MetricRecorder metricRecorder in recorders)\n            {\n                metricRecorder.Recorder.Dispose();\n            }\n\n            recorders.Clear();\n        }\n\n        private void AddRecorder(string markerName, int capacity)\n        {\n            const ProfilerRecorderOptions options =\n                ProfilerRecorderOptions.StartImmediately |\n                ProfilerRecorderOptions.SumAllSamplesInFrame |\n                ProfilerRecorderOptions.WrapAroundWhenCapacityReached;\n\n            ProfilerRecorder recorder =\n                ProfilerRecorder.StartNew(\n                    ProfilerCategory.Scripts,\n                    markerName,\n                    capacity,\n                    options);\n\n            recorders.Add(new MetricRecorder(markerName, recorder));\n        }\n\n        private readonly struct MetricRecorder\n        {\n            public string MarkerName { get; }\n            public ProfilerRecorder Recorder { get; }\n\n            public MetricRecorder(\n                string markerName,\n                ProfilerRecorder recorder)\n            {\n                MarkerName = markerName;\n                Recorder = recorder;\n            }\n        }\n    }\n}\n","Performance/InputComparison/LinearDragBenchmarkSequenceFactory.cs":"using System;\r\nusing UnityEngine;\r\n\r\nnamespace Shield_Shot.Performance.InputComparison\r\n{\r\n    public static class LinearDragBenchmarkSequenceFactory\r\n    {\r\n        public static BenchmarkPointerSequence Create(\r\n            string sequenceId,\r\n            int pointerId,\r\n            Vector2 startPosition,\r\n            Vector2 endPosition,\r\n            double durationSeconds,\r\n            int samplesPerSecond)\r\n        {\r\n            ValidateArguments(\r\n                startPosition,\r\n                endPosition,\r\n                durationSeconds,\r\n                samplesPerSecond);\r\n\r\n            int intervalCount =\r\n                CalculateIntervalCount(\r\n                    durationSeconds,\r\n                    samplesPerSecond);\r\n\r\n            var samples =\r\n                new BenchmarkPointerSample[\r\n                    intervalCount + 1];\r\n\r\n            for (int index = 0;\r\n                 index \u003c= intervalCount;\r\n                 index++)\r\n            {\r\n                float progress =\r\n                    (float)index /\r\n                    intervalCount;\r\n\r\n                Vector2 position =\r\n                    Vector2.Lerp(\r\n                        startPosition,\r\n                        endPosition,\r\n                        progress);\r\n\r\n                double timestamp =\r\n                    durationSeconds *\r\n                    index /\r\n                    intervalCount;\r\n\r\n                BenchmarkPointerPhase phase =\r\n                    ResolvePhase(\r\n                        index,\r\n                        intervalCount);\r\n\r\n                samples[index] =\r\n                    new BenchmarkPointerSample(\r\n                        pointerId,\r\n                        phase,\r\n                        position,\r\n                        timestamp);\r\n            }\r\n\r\n            return new BenchmarkPointerSequence(\r\n                sequenceId,\r\n                samples);\r\n        }\r\n\r\n        private static BenchmarkPointerPhase ResolvePhase(\r\n            int index,\r\n            int intervalCount)\r\n        {\r\n            if (index == 0)\r\n            {\r\n                return BenchmarkPointerPhase.Began;\r\n            }\r\n\r\n            if (index == intervalCount)\r\n            {\r\n                return BenchmarkPointerPhase.Ended;\r\n            }\r\n\r\n            return BenchmarkPointerPhase.Moved;\r\n        }\r\n\r\n        private static int CalculateIntervalCount(\r\n            double durationSeconds,\r\n            int samplesPerSecond)\r\n        {\r\n            double calculatedCount =\r\n                Math.Ceiling(\r\n                    durationSeconds *\r\n                    samplesPerSecond);\r\n\r\n            if (calculatedCount \u003e\r\n                int.MaxValue - 1)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(durationSeconds),\r\n                    \"Requested sequence is too large.\");\r\n            }\r\n\r\n            return Math.Max(\r\n                1,\r\n                (int)calculatedCount);\r\n        }\r\n\r\n        private static void ValidateArguments(\r\n            Vector2 startPosition,\r\n            Vector2 endPosition,\r\n            double durationSeconds,\r\n            int samplesPerSecond)\r\n        {\r\n            ValidateNormalizedPosition(\r\n                startPosition,\r\n                nameof(startPosition));\r\n\r\n            ValidateNormalizedPosition(\r\n                endPosition,\r\n                nameof(endPosition));\r\n\r\n            if (double.IsNaN(durationSeconds) ||\r\n                double.IsInfinity(durationSeconds) ||\r\n                durationSeconds \u003c= 0d)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(durationSeconds),\r\n                    durationSeconds,\r\n                    \"Duration must be finite and positive.\");\r\n            }\r\n\r\n            if (samplesPerSecond \u003c= 0)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(samplesPerSecond),\r\n                    samplesPerSecond,\r\n                    \"Samples per second must be positive.\");\r\n            }\r\n        }\r\n\r\n        private static void ValidateNormalizedPosition(\r\n            Vector2 position,\r\n            string parameterName)\r\n        {\r\n            if (!IsFinite(position.x) ||\r\n                !IsFinite(position.y) ||\r\n                position.x \u003c 0f ||\r\n                position.x \u003e 1f ||\r\n                position.y \u003c 0f ||\r\n                position.y \u003e 1f)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    parameterName,\r\n                    position,\r\n                    \"Position must be finite and normalized.\");\r\n            }\r\n        }\r\n\r\n        private static bool IsFinite(float value)\r\n        {\r\n            return\r\n                !float.IsNaN(value) \u0026\u0026\r\n                !float.IsInfinity(value);\r\n        }\r\n    }\r\n}","Performance/InputComparison/V1BenchmarkInputAdapter.cs":"using System;\r\nusing Shield_Shot.InputSystem;\r\nusing UnityEngine;\r\nusing Unity.Profiling;\r\n\r\nusing LegacyTouchPhase =\r\n    UnityEngine.InputSystem.TouchPhase;\r\n\r\nnamespace Shield_Shot.Performance.InputComparison\r\n{\r\n    public sealed class V1BenchmarkInputAdapter\r\n        : MonoBehaviour,\r\n          IBenchmarkPointerInputTarget\r\n    {\r\n        [SerializeField]\r\n        private TouchRouter touchRouter;\r\n\r\n        [SerializeField]\r\n        private InputProvider liveInputProvider;\r\n\r\n        private Vector2 viewportSize;\r\n        private bool sequenceActive;\r\n\r\n        private static readonly ProfilerMarker\r\n    ProcessSamplesMarker =\r\n        new ProfilerMarker(\r\n            \"Input.V1.ProcessSamples\");\r\n\r\n        public void BeginSequence(\r\n            Vector2 viewportSize,\r\n            double startTimestamp)\r\n        {\r\n            if (touchRouter == null)\r\n            {\r\n                throw new InvalidOperationException(\r\n                    \"V1 TouchRouter is not assigned.\");\r\n            }\r\n\r\n            if (liveInputProvider == null)\r\n            {\r\n                throw new InvalidOperationException(\r\n                    \"V1 InputProvider is not assigned.\");\r\n            }\r\n\r\n            ValidateViewportSize(\r\n                viewportSize);\r\n\r\n            if (double.IsNaN(startTimestamp) ||\r\n                double.IsInfinity(startTimestamp) ||\r\n                startTimestamp \u003c 0d)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(startTimestamp),\r\n                    startTimestamp,\r\n                    \"Start timestamp must be finite \" +\r\n                    \"and non-negative.\");\r\n            }\r\n\r\n            liveInputProvider.enabled = false;\r\n\r\n            this.viewportSize =\r\n                viewportSize;\r\n\r\n            touchRouter.ResetRouting(\r\n                notifyCancellation: true);\r\n\r\n            sequenceActive = true;\r\n        }\r\n\r\n        public void Receive(\r\n            in BenchmarkPointerSample sample)\r\n        {\r\n            if (!sequenceActive)\r\n            {\r\n                throw new InvalidOperationException(\r\n                    \"BeginSequence must be called \" +\r\n                    \"before receiving samples.\");\r\n            }\r\n\r\n            ProcessSamplesMarker.Begin();\r\n\r\n\r\n            try\r\n            {\r\n                Vector2 screenPosition =\r\n                    sample.ToScreenPosition(\r\n                        viewportSize);\r\n\r\n                LegacyTouchPhase phase =\r\n                    ConvertPhase(\r\n                        sample.Phase);\r\n\r\n                touchRouter.ProcessTouch(\r\n                    sample.PointerId,\r\n                    screenPosition,\r\n                    phase);\r\n            }\r\n            finally\r\n            {\r\n                ProcessSamplesMarker.End();\r\n            }\r\n        }\r\n\r\n        public void CompleteFrame()\r\n        {\r\n            /*\r\n             * V1���� ������ ���� Coalescing�� �����Ƿ�\r\n             * ������ �۾��� ����.\r\n             */\r\n        }\r\n\r\n        public void EndSequence()\r\n        {\r\n            if (!sequenceActive)\r\n            {\r\n                return;\r\n            }\r\n\r\n            try\r\n            {\r\n                touchRouter?.ResetRouting(\r\n                    notifyCancellation: true);\r\n            }\r\n            finally\r\n            {\r\n                sequenceActive = false;\r\n                viewportSize = Vector2.zero;\r\n            }\r\n        }\r\n\r\n        private static LegacyTouchPhase ConvertPhase(\r\n            BenchmarkPointerPhase phase)\r\n        {\r\n            switch (phase)\r\n            {\r\n                case BenchmarkPointerPhase.Began:\r\n                    return LegacyTouchPhase.Began;\r\n\r\n                case BenchmarkPointerPhase.Moved:\r\n                    return LegacyTouchPhase.Moved;\r\n\r\n                case BenchmarkPointerPhase.Stationary:\r\n                    return LegacyTouchPhase.Stationary;\r\n\r\n                case BenchmarkPointerPhase.Ended:\r\n                    return LegacyTouchPhase.Ended;\r\n\r\n                case BenchmarkPointerPhase.Canceled:\r\n                    return LegacyTouchPhase.Canceled;\r\n\r\n                default:\r\n                    throw new ArgumentOutOfRangeException(\r\n                        nameof(phase),\r\n                        phase,\r\n                        \"Unsupported benchmark phase.\");\r\n            }\r\n        }\r\n\r\n        private static void ValidateViewportSize(\r\n            Vector2 size)\r\n        {\r\n            if (!IsFinite(size.x) ||\r\n                !IsFinite(size.y) ||\r\n                size.x \u003c= 0f ||\r\n                size.y \u003c= 0f)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(size),\r\n                    size,\r\n                    \"Viewport size must be finite \" +\r\n                    \"and positive.\");\r\n            }\r\n        }\r\n\r\n        private static bool IsFinite(float value)\r\n        {\r\n            return\r\n                !float.IsNaN(value) \u0026\u0026\r\n                !float.IsInfinity(value);\r\n        }\r\n\r\n        public void ResumeLiveInput()\r\n        {\r\n            if (sequenceActive)\r\n            {\r\n                EndSequence();\r\n            }\r\n\r\n            if (liveInputProvider != null)\r\n            {\r\n                liveInputProvider.enabled = true;\r\n            }\r\n        }\r\n    }\r\n}","Performance/InputComparison/V2BenchmarkInputAdapter.cs":"using System;\r\nusing Shield_Shot.InputSystemV2.Domain;\r\nusing Shield_Shot.InputSystemV2.Integration;\r\nusing UnityEngine;\r\nusing Unity.Profiling;\r\n\r\nnamespace Shield_Shot.Performance.InputComparison\r\n{\r\n    public sealed class V2BenchmarkInputAdapter\r\n        : MonoBehaviour,\r\n          IBenchmarkPointerInputTarget\r\n    {\r\n        [SerializeField]\r\n        private InputSystemV2RuntimeBehaviour runtime;\r\n\r\n        private Vector2 viewportSize;\r\n        private double startTimestamp;\r\n        private bool sequenceActive;\r\n\r\n        private static readonly ProfilerMarker\r\n    ProcessSamplesMarker =\r\n        new ProfilerMarker(\r\n            \"Input.V2.ProcessSamples\");\r\n\r\n        private static readonly ProfilerMarker\r\n            CompleteFrameMarker =\r\n                new ProfilerMarker(\r\n                    \"Input.V2.CompleteFrame\");\r\n\r\n        public void BeginSequence(\r\n            Vector2 viewportSize,\r\n            double startTimestamp)\r\n        {\r\n            if (runtime == null)\r\n            {\r\n                throw new InvalidOperationException(\r\n                    \"Input System V2 Runtime is not assigned.\");\r\n            }\r\n\r\n            ValidateViewportSize(\r\n                viewportSize);\r\n\r\n            if (double.IsNaN(startTimestamp) ||\r\n                double.IsInfinity(startTimestamp) ||\r\n                startTimestamp \u003c 0d)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(startTimestamp),\r\n                    startTimestamp,\r\n                    \"Start timestamp must be finite \" +\r\n                    \"and non-negative.\");\r\n            }\r\n\r\n            if (sequenceActive)\r\n            {\r\n                throw new InvalidOperationException(\r\n                    \"A benchmark sequence is already active.\");\r\n            }\r\n\r\n            this.viewportSize =\r\n                viewportSize;\r\n\r\n            this.startTimestamp =\r\n                startTimestamp;\r\n\r\n            runtime.BeginExternalInput();\r\n            sequenceActive = true;\r\n        }\r\n\r\n        public void Receive(\r\n    in BenchmarkPointerSample sample)\r\n        {\r\n            if (!sequenceActive)\r\n            {\r\n                throw new InvalidOperationException(\r\n                    \"BeginSequence must be called \" +\r\n                    \"before receiving samples.\");\r\n            }\r\n\r\n            ProcessSamplesMarker.Begin();\r\n\r\n            try\r\n            {\r\n                Vector2 screenPosition =\r\n                    sample.ToScreenPosition(\r\n                        viewportSize);\r\n\r\n                PointerSample pointerSample =\r\n                    new PointerSample(\r\n                        pointerId:\r\n                            sample.PointerId,\r\n\r\n                        deviceKind:\r\n                            PointerDeviceKind.Touch,\r\n\r\n                        phase:\r\n                            ConvertPhase(\r\n                                sample.Phase),\r\n\r\n                        screenPosition:\r\n                            screenPosition,\r\n\r\n                        timestamp:\r\n                            startTimestamp +\r\n                            sample.TimestampOffset);\r\n\r\n                runtime.SubmitExternalSample(\r\n                    in pointerSample);\r\n            }\r\n            finally\r\n            {\r\n                ProcessSamplesMarker.End();\r\n            }\r\n        }\r\n\r\n        public void CompleteFrame()\r\n        {\r\n            if (!sequenceActive)\r\n            {\r\n                return;\r\n            }\r\n\r\n            CompleteFrameMarker.Begin();\r\n\r\n            try\r\n            {\r\n                runtime.CompleteExternalFrame();\r\n            }\r\n            finally\r\n            {\r\n                CompleteFrameMarker.End();\r\n            }\r\n        }\r\n\r\n        public void EndSequence()\r\n        {\r\n            if (!sequenceActive)\r\n            {\r\n                return;\r\n            }\r\n\r\n            runtime.EndExternalInput();\r\n\r\n            sequenceActive = false;\r\n            viewportSize = Vector2.zero;\r\n            startTimestamp = 0d;\r\n        }\r\n\r\n        public void ResumeLiveInput()\r\n        {\r\n            if (sequenceActive)\r\n            {\r\n                EndSequence();\r\n            }\r\n\r\n            runtime?.ResumeLiveInput();\r\n        }\r\n\r\n        private static PointerPhase ConvertPhase(\r\n            BenchmarkPointerPhase phase)\r\n        {\r\n            switch (phase)\r\n            {\r\n                case BenchmarkPointerPhase.Began:\r\n                    return PointerPhase.Began;\r\n\r\n                case BenchmarkPointerPhase.Moved:\r\n                    return PointerPhase.Moved;\r\n\r\n                case BenchmarkPointerPhase.Stationary:\r\n                    return PointerPhase.Stationary;\r\n\r\n                case BenchmarkPointerPhase.Ended:\r\n                    return PointerPhase.Ended;\r\n\r\n                case BenchmarkPointerPhase.Canceled:\r\n                    return PointerPhase.Canceled;\r\n\r\n                default:\r\n                    throw new ArgumentOutOfRangeException(\r\n                        nameof(phase),\r\n                        phase,\r\n                        \"Unsupported benchmark phase.\");\r\n            }\r\n        }\r\n\r\n        private static void ValidateViewportSize(\r\n            Vector2 size)\r\n        {\r\n            if (!IsFinite(size.x) ||\r\n                !IsFinite(size.y) ||\r\n                size.x \u003c= 0f ||\r\n                size.y \u003c= 0f)\r\n            {\r\n                throw new ArgumentOutOfRangeException(\r\n                    nameof(size),\r\n                    size,\r\n                    \"Viewport size must be finite \" +\r\n                    \"and positive.\");\r\n            }\r\n        }\r\n\r\n        private static bool IsFinite(float value)\r\n        {\r\n            return\r\n                !float.IsNaN(value) \u0026\u0026\r\n                !float.IsInfinity(value);\r\n        }\r\n    }\r\n}"});
